window.BUZZ_COURSE_V2_LESSONS = Object.assign(window.BUZZ_COURSE_V2_LESSONS || {}, {"asymptotes":{"id":"asymptotes","prerequisites":["limit-at-infinity","infinite-limits","polynomial-rational"],"next":["curve-sketching-1"],"related":["limit-factor","limit-rationalize"],"objectives":["用單邊極限判斷垂直漸近線，分清楚「洞」與垂直漸近線","$x\\to\\infty$ 與 $x\\to-\\infty$ 分開算，求出水平漸近線（最多兩條）","用長除法求有理函數的斜漸近線，並說出它的定義：$f(x)-(mx+b)\\to 0$"],"concept":[{"heading":"① 越走越貼近的直線","body":["漸近線：曲線沿著它走，距離越來越小、趨近 $0$ 的直線","三種：","• 垂直：$x=a$，函數值衝到 $\\pm\\infty$","• 水平：$y=L$，$x$ 往 $\\pm\\infty$ 時貼近","• 斜：$y=mx+b$（$m\\ne0$），$x$ 往 $\\pm\\infty$ 時貼近","用處：先畫漸近線，曲線就有了骨架","漸近線可以被穿過：只要求「在遠處」貼近","垂直漸近線 $x=a$ 才真的碰不到：$a$ 附近函數值無界"]},{"heading":"② 垂直漸近線與洞","body":["定義：只要有一側","就說 $x=a$ 是垂直漸近線","有理函數：先約分，再看分母的零點","例：$y=\\dfrac{x-1}{(x^2-1)(x^2-4)}$ 有幾條垂直漸近線？","分母的零點：$x=\\pm1,\\ \\pm2$，四個候選","約分只在 $x\\ne1$ 時成立","• $x=1$：約掉了 → 洞，在 $\\big(1,\\,-\\frac16\\big)$","• $x=-1,\\ 2,\\ -2$：約完分母是 $0$、分子是 $1$"],"tex":["\\lim_{x\\to a^+}f(x)=\\pm\\infty\\ \\text{或}\\ \\lim_{x\\to a^-}f(x)=\\pm\\infty","\\frac{x-1}{(x-1)(x+1)(x-2)(x+2)}=\\frac{1}{(x+1)(x-2)(x+2)}","\\text{答：3 條}\\quad x=-2,\\ x=-1,\\ x=2"]},{"heading":"② 用單邊極限確認","body":["在 $x=2$：$\\dfrac{1}{(x+1)(x+2)}\\to\\dfrac1{12}>0$，剩下 $\\dfrac1{x-2}$","• $x\\to2^+$：$x-2\\to0^+$ → $+\\infty$","• $x\\to2^-$：$x-2\\to0^-$ → $-\\infty$","數值：$f(2.0001)\\approx833$，$f(1.9999)\\approx-833$","在 $x=1$：$\\displaystyle\\lim_{x\\to1}f(x)=-\\frac16$，有限 → 不是漸近線"]},{"heading":"③ 水平漸近線","body":["定義：若","則 $y=L$ 是水平漸近線","兩個方向分開算：答案可能不一樣","例：$f(x)=\\dfrac{x}{\\sqrt{x^2+1}}$ 的水平漸近線","$\\sqrt{x^2+1}=\\sqrt{x^2}\\sqrt{1+\\frac1{x^2}}=|x|\\sqrt{1+\\frac1{x^2}}$","$x\\to\\infty$：$|x|=x$","$x\\to-\\infty$：$|x|=-x$"],"tex":["\\lim_{x\\to\\infty}f(x)=L\\quad\\text{或}\\quad\\lim_{x\\to-\\infty}f(x)=L","f(x)=\\frac{x}{x\\sqrt{1+\\frac1{x^2}}}\\to\\frac11=1","f(x)=\\frac{x}{-x\\sqrt{1+\\frac1{x^2}}}\\to-1","\\text{兩條：}\\ y=1\\ \\text{（右邊）},\\quad y=-1\\ \\text{（左邊）}"]},{"heading":"③ 看圖、再一例","body":["有理函數兩頭的極限一定一樣 → 最多一條","例：$y=e^x$ 只有左邊的 $y=0$；$y=\\arctan x$ 有 $y=\\pm\\frac\\pi2$ 兩條","例：$f(x)=\\dfrac{3x^2+x}{x^2+1}$（次數一樣）","同除以 $x^2$：$\\dfrac{3+\\frac1x}{1+\\frac1{x^2}}\\to3$","穿過去了：$f(x)=3\\iff3x^2+x=3x^2+3\\iff x=3$"],"tex":["\\text{水平漸近線}\\ y=3"]},{"heading":"③ 穿過也沒關係","body":["$f(x)-3=\\frac{x-3}{x^2+1}$：$x<3$ 為負（在下方），$x>3$ 為正（在上方）"]},{"heading":"④ 斜漸近線","body":["定義：若","則 $y=mx+b$ 是斜漸近線（$x\\to-\\infty$ 也一樣）","有理函數：分子比分母高一次時出現","例：$y=\\dfrac{x^2+2x+3}{x}$ 的斜漸近線是 $y=x+k$，求 $k$","逐項除：$y=x+2+\\dfrac3x$","想法：商式是那條直線，餘式除以分母趨近 $0$"],"tex":["\\lim_{x\\to\\infty}\\big[f(x)-(mx+b)\\big]=0\\quad(m\\ne0)","y-(x+2)=\\frac3x\\to0\\quad(x\\to\\pm\\infty)","\\text{斜漸近線}\\ y=x+2,\\quad k=2"]},{"heading":"④ 用長除法","body":["例：$y=\\dfrac{2x^2-3x+1}{x+1}$","• $2x^2\\div x=2x$：減去 $2x(x+1)=2x^2+2x$，剩 $-5x+1$","• $-5x\\div x=-5$：減去 $-5(x+1)=-5x-5$，剩 $6$","驗算：$(x+1)(2x-5)+6=2x^2-3x-5+6$","$\\dfrac6{x+1}\\to0$ → 斜漸近線 $y=2x-5$；垂直漸近線 $x=-1$","有理函數：次數差 $\\le0$ → 水平；差 $=1$ → 斜；差 $\\ge2$ → 都沒有","差 $\\ge2$ 時商式是二次以上，曲線彎上去，貼不到直線"],"tex":["\\frac{2x^2-3x+1}{x+1}=2x-5+\\frac{6}{x+1}"]},{"heading":"④ 試一題","body":["不是有理函數：用定義反推","例：$\\sqrt{x^2+2x}$ 往右貼 $y=x+1$，往左貼 $y=-x-1$"],"tex":["m=\\lim_{x\\to\\infty}\\frac{f(x)}{x},\\quad b=\\lim_{x\\to\\infty}\\big[f(x)-mx\\big]"]},{"heading":"重點整理","body":["• 垂直 $x=a$：有一側極限是 $\\pm\\infty$；有理函數先約分，約掉的是洞","• 水平 $y=L$：$x\\to\\infty$、$x\\to-\\infty$ 分開算，最多兩條","• 斜 $y=mx+b$：$f(x)-(mx+b)\\to0$；有理函數用長除法取商","• 水平、斜漸近線可以被穿過","下一課：函數完整分析 I：用漸近線當骨架"]}],"workedExamples":[{"title":"垂直漸近線還是洞","prompt":"$y=\\frac{x-1}{(x^2-1)(x^2-4)}$ 有幾條垂直漸近線？","problemId":"cx-curve-006","steps":["分母因式分解：$(x-1)(x+1)(x-2)(x+2)$。$x\\ne 1$ 時約掉 $x-1$，得 $y=\\frac{1}{(x+1)(x-2)(x+2)}$。","$x=1$：約分後的式子在 $1$ 有定義，極限是 $\\frac{1}{2\\cdot(-1)\\cdot 3}=-\\frac{1}{6}$，圖形在 $(1,-\\frac{1}{6})$ 挖洞，不是漸近線。","$x=-1$、$2$、$-2$：約分後分子是 $1$、分母趨近 $0$，單邊極限是 $\\pm\\infty$，都是垂直漸近線。","共 3 條：$x=-2$、$x=-1$、$x=2$。"],"answer":"3 條"},{"title":"兩條水平漸近線","prompt":"求 $f(x)=\\frac{x}{\\sqrt{x^2+1}}$ 的水平漸近線。","steps":["先把根號裡的 $x^2$ 提出來：$\\sqrt{x^2+1}=\\sqrt{x^2}\\cdot\\sqrt{1+\\frac{1}{x^2}}=|x|\\sqrt{1+\\frac{1}{x^2}}$。","$x\\to\\infty$（$x>0$，$|x|=x$）：$f(x)=\\frac{x}{x\\sqrt{1+\\frac{1}{x^2}}}=\\frac{1}{\\sqrt{1+\\frac{1}{x^2}}}\\to 1$。","$x\\to-\\infty$（$x<0$，$|x|=-x$）：$f(x)=\\frac{x}{-x\\sqrt{1+\\frac{1}{x^2}}}=-\\frac{1}{\\sqrt{1+\\frac{1}{x^2}}}\\to-1$。","水平漸近線是 $y=1$（右邊）與 $y=-1$（左邊）。分母 $\\sqrt{x^2+1}\\ge 1$ 不為 $0$，沒有垂直漸近線。"],"answer":"$y=1$ 與 $y=-1$"},{"title":"斜漸近線","prompt":"$y=\\frac{x^2+2x+3}{x}$ 的斜漸近線是 $y=x+k$，求 $k$。","problemId":"cx-curve-005","steps":["分子分母次數 2 比 1，多一次，會有斜漸近線。除法：$\\frac{x^2+2x+3}{x}=x+2+\\frac{3}{x}$。","$x\\to\\pm\\infty$ 時 $\\frac{3}{x}\\to 0$，所以 $y-(x+2)\\to 0$，斜漸近線是 $y=x+2$，$k=2$。","順便：$x=0$ 時分子是 $3\\ne 0$、分母是 $0$，$x=0$ 是垂直漸近線。"],"answer":"$k=2$"},{"title":"次數一樣：找水平漸近線","prompt":"求 $f(x)=\\frac{3x^2+x}{x^2+1}$ 的水平漸近線。","steps":["分子分母最高次都是 $x^2$，上下同除以 $x^2$：$f(x)=\\frac{3+\\frac{1}{x}}{1+\\frac{1}{x^2}}$。","$x\\to\\infty$ 時 $\\frac{1}{x}\\to 0$、$\\frac{1}{x^2}\\to 0$，所以 $f(x)\\to\\frac{3}{1}=3$。","$x\\to-\\infty$ 一樣得 $3$，水平漸近線是 $y=3$。"],"answer":"$y=3$"}],"pitfalls":["分母為 $0$ 就說是垂直漸近線，沒先約分（會把洞當成漸近線）。","只算 $x\\to\\infty$，忘了 $x\\to-\\infty$ 可能是另一條。","$x\\to-\\infty$ 時把 $\\sqrt{x^2}$ 寫成 $x$，正負號全錯。","以為曲線永遠碰不到水平漸近線。","長除法的商寫成斜漸近線，卻忘了先確認分子只比分母多一次。"],"voice":"73844192","sections":[{"title":"越走越貼近的直線","beats":[{"show":["漸近線：曲線沿著它走，距離越來越小、趨近 $0$ 的直線"],"say":"這一課把漸近線整理清楚。漸近線是一條直線，曲線沿著它走，距離越來越小，趨近 0。","board":[{"do":"write","line":"漸近線：曲線沿著它走，距離越來越小、趨近 $0$ 的直線","color":"gold"}],"t":[2280,16840]},{"show":["三種：","• 垂直：$x=a$，函數值衝到 $\\pm\\infty$"],"say":"一共三種。垂直的，是 x 靠近某個數時，函數值往上或往下衝。水平的和斜的，是 x 往兩頭走很遠時，曲線貼近的直線。","board":[{"do":"write","line":"三種："},{"do":"write","line":"• 垂直：$x=a$，函數值衝到 $\\pm\\infty$","on":"近某"},{"do":"write","line":"• 水平：$y=L$，$x$ 往 $\\pm\\infty$ 時貼近","on":"水平"},{"do":"write","line":"• 斜：$y=mx+b$（$m\\ne0$），$x$ 往 $\\pm\\infty$ 時貼近","on":"兩頭"}],"t":[16840,30920]},{"show":["用處：先畫漸近線，曲線就有了骨架"],"say":"畫函數圖時，先畫漸近線，曲線就有了骨架。這是下兩課完整作圖的第一步。","board":[{"do":"write","line":"用處：先畫漸近線，曲線就有了骨架"}],"t":[30920,40700]},{"show":["一條垂直（x = 0）、一條斜（y = x+2）"],"say":"看這個例子。紅線是兩條漸近線：垂直的 x 等於 0，斜的 y 等於 x 加 2。藍色曲線在中間上下衝，往兩頭就貼著斜線。","board":[{"do":"plot","nb":{"spec":{"id":"three","window":[-6,6,-6,8],"fn":[{"expr":"(x^2+2*x+3)/x","color":"blue","label":"y = (x²+2x+3)/x"},{"expr":"x+2","color":"red","dash":true,"label":"y = x+2"}],"vlines":[{"x":0,"label":"x = 0","color":"red"}],"height":300}}},{"do":"write","line":"一條垂直（x = 0）、一條斜（y = x+2）","color":"violet","on":"等於#2"}],"t":[40700,53940]},{"show":["漸近線可以被穿過：只要求「在遠處」貼近"],"say":"常見的誤會是：曲線不能碰到漸近線。其實水平和斜漸近線只管很遠的地方，中間穿過去沒關係。","board":[{"do":"write","line":"漸近線可以被穿過：只要求「在遠處」貼近","color":"red"},{"do":"write","line":"　垂直漸近線 $x=a$ 才真的碰不到：$a$ 附近函數值無界","color":"violet","on":"和斜"}],"t":[53940,69190]}]},{"title":"垂直漸近線與洞","beats":[{"show":["定義：只要有一側","$\\lim_{x\\to a^+}f(x)=\\pm\\infty\\ \\text{或}\\ \\lim_{x\\to a^-}f(x)=\\pm\\infty$"],"say":"垂直漸近線的定義：x 從右邊或左邊靠近 a，只要有一側的極限是正負無限大，x 等於 a 就是垂直漸近線。","board":[{"do":"write","line":"定義：只要有一側"},{"do":"write","line":"$\\displaystyle \\lim_{x\\to a^+}f(x)=\\pm\\infty\\ \\text{或}\\ \\lim_{x\\to a^-}f(x)=\\pm\\infty$","on":"靠近"},{"do":"write","line":"就說 $x=a$ 是垂直漸近線","color":"gold","on":"限大"}],"t":[69190,79990]},{"show":["有理函數：先約分，再看分母的零點"],"say":"有理函數的候選人是分母的零點。但要先約分：約掉的只是洞，約不掉的才是漸近線。","board":[{"do":"write","line":"有理函數：先約分，再看分母的零點"}],"t":[79990,89600]},{"show":["例：$y=\\dfrac{x-1}{(x^2-1)(x^2-4)}$ 有幾條垂直漸近線？"],"say":"例子：x 減 1，除以 x 平方減 1 乘 x 平方減 4。有幾條垂直漸近線？","board":[{"do":"write","line":"例：$y=\\dfrac{x-1}{(x^2-1)(x^2-4)}$ 有幾條垂直漸近線？"}],"t":[89600,98160]},{"show":["分母的零點：$x=\\pm1,\\ \\pm2$，四個候選"],"say":"分母在正負 1、正負 2 都是 0，四個候選人。先別急著說四條。","board":[{"do":"write","line":"分母的零點：$x=\\pm1,\\ \\pm2$，四個候選"}],"t":[98160,106760]},{"show":["$\\frac{x-1}{(x-1)(x+1)(x-2)(x+2)}=\\frac{1}{(x+1)(x-2)(x+2)}$"],"say":"分母完全分解以後，分子的 x 減 1 可以約掉。","board":[{"do":"write","line":"$\\displaystyle \\frac{x-1}{(x-1)(x+1)(x-2)(x+2)}=\\frac{1}{(x+1)(x-2)(x+2)}$"},{"do":"write","line":"　約分只在 $x\\ne1$ 時成立","color":"violet","on":"可以"}],"t":[106760,111980]},{"show":["• $x=1$：約掉了 → 洞，在 $\\big(1,\\,-\\frac16\\big)$"],"say":"x 等於 1 被約掉，只是洞。代進約完的式子，2 乘負 1 乘 3 是負 6，洞在 1 逗號負 6 分之 1。","board":[{"do":"write","line":"• $x=1$：約掉了 → 洞，在 $\\big(1,\\,-\\frac16\\big)$"}],"t":[111980,123380]},{"show":["• $x=-1,\\ 2,\\ -2$：約完分母是 $0$、分子是 $1$"],"say":"其他三個，約完分母是 0、分子是 1，會衝到無限大。","board":[{"do":"write","line":"• $x=-1,\\ 2,\\ -2$：約完分母是 $0$、分子是 $1$"}],"t":[123380,129750]},{"show":["$\\text{答：3 條}\\quad x=-2,\\ x=-1,\\ x=2$"],"say":"答案是三條：x 等於負 2、負 1、和 2。","board":[{"do":"write","line":"${{bx1:\\displaystyle \\text{答：3 條}\\quad x=-2,\\ x=-1,\\ x=2}}$","color":"red"},{"do":"box","term":"bx1","color":"red","on":"2。"}],"t":[129750,135830]}]},{"title":"用單邊極限確認","beats":[{"show":["在 $x=2$：$\\dfrac{1}{(x+1)(x+2)}\\to\\dfrac1{12}>0$，剩下 $\\dfrac1{x-2}$"],"say":"用單邊極限確認 x 等於 2。另外兩個因式趨近 12 分之 1，是正的，正負號只看 x 減 2。","board":[{"do":"write","line":"在 $x=2$：$\\dfrac{1}{(x+1)(x+2)}\\to\\dfrac1{12}>0$，剩下 $\\dfrac1{x-2}$"}],"t":[135830,147530]},{"show":["• $x\\to2^+$：$x-2\\to0^+$ → $+\\infty$","• $x\\to2^-$：$x-2\\to0^-$ → $-\\infty$"],"say":"右邊是很小的正數，往正無限大；左邊是很小的負數，往負無限大。確定是垂直漸近線。","board":[{"do":"write","line":"• $x\\to2^+$：$x-2\\to0^+$ → $+\\infty$"},{"do":"write","line":"• $x\\to2^-$：$x-2\\to0^-$ → $-\\infty$","on":"左邊"},{"do":"write","line":"　數值：$f(2.0001)\\approx833$，$f(1.9999)\\approx-833$","color":"violet","on":"無限#2"}],"t":[147530,157670]},{"show":["在 $x=1$：$\\displaystyle\\lim_{x\\to1}f(x)=-\\frac16$，有限 → 不是漸近線"],"say":"反過來，x 趨近 1 的極限是負 6 分之 1，有限，所以只是洞。","board":[{"do":"write","line":"在 $x=1$：$\\displaystyle\\lim_{x\\to1}f(x)=-\\frac16$，有限 → 不是漸近線"}],"t":[157670,165370]},{"show":["三條垂直漸近線；x = 1 只是空心的洞"],"say":"圖上，三條紅線旁曲線都上下衝；x 等於 1 那裡平順經過，只少一個點。","board":[{"do":"plot","nb":{"spec":{"id":"vah","window":[-4,4,-2,2],"fn":[{"expr":"(x-1)/((x^2-1)*(x^2-4))","color":"blue"}],"vlines":[{"x":-2,"color":"red"},{"x":-1,"color":"red"},{"x":2,"color":"red"}],"points":[{"x":1,"y":"-1/6","color":"blue","open":true}],"height":280}}},{"do":"write","line":"三條垂直漸近線；x = 1 只是空心的洞","color":"violet","on":"等於"}],"t":[165370,173540]}],"check":0},{"title":"水平漸近線","beats":[{"show":["定義：若","$\\lim_{x\\to\\infty}f(x)=L\\quad\\text{或}\\quad\\lim_{x\\to-\\infty}f(x)=L$"],"say":"水平漸近線：x 往正無限大或負無限大，只要函數趨近一個數 L，y 等於 L 就是水平漸近線。","board":[{"do":"write","line":"定義：若"},{"do":"write","line":"$\\displaystyle \\lim_{x\\to\\infty}f(x)=L\\quad\\text{或}\\quad\\lim_{x\\to-\\infty}f(x)=L$","on":"無限#2"},{"do":"write","line":"則 $y=L$ 是水平漸近線","color":"gold","on":"等於"}],"t":[186770,196580]},{"show":["兩個方向分開算：答案可能不一樣"],"say":"兩個方向要分開算。答案可能不一樣，所以最多有兩條。","board":[{"do":"write","line":"兩個方向分開算：答案可能不一樣","color":"red"}],"t":[196580,203550]},{"show":["例：$f(x)=\\dfrac{x}{\\sqrt{x^2+1}}$ 的水平漸近線"],"say":"例子：x 除以根號 x 平方加 1。","board":[{"do":"write","line":"例：$f(x)=\\dfrac{x}{\\sqrt{x^2+1}}$ 的水平漸近線"}],"t":[203550,207950]},{"show":["$\\sqrt{x^2+1}=\\sqrt{x^2}\\sqrt{1+\\frac1{x^2}}=|x|\\sqrt{1+\\frac1{x^2}}$"],"say":"把 x 平方提出根號。關鍵：根號 x 平方是 x 的絕對值，不是 x。","board":[{"do":"write","line":"$\\sqrt{x^2+1}=\\sqrt{x^2}\\sqrt{1+\\frac1{x^2}}=|x|\\sqrt{1+\\frac1{x^2}}$"}],"t":[207950,217760]},{"show":["$x\\to\\infty$：$|x|=x$","$f(x)=\\frac{x}{x\\sqrt{1+\\frac1{x^2}}}\\to\\frac11=1$"],"say":"往右，x 是正的，絕對值就是 x，約掉趨近 1。","board":[{"do":"write","line":"$x\\to\\infty$：$|x|=x$"},{"do":"write","line":"$\\displaystyle f(x)=\\frac{x}{x\\sqrt{1+\\frac1{x^2}}}\\to\\frac11=1$","on":"就是"}],"t":[217760,224790]},{"show":["$x\\to-\\infty$：$|x|=-x$","$f(x)=\\frac{x}{-x\\sqrt{1+\\frac1{x^2}}}\\to-1$"],"say":"往左，x 是負的，絕對值是負 x，約掉剩負 1。","board":[{"do":"write","line":"$x\\to-\\infty$：$|x|=-x$"},{"do":"write","line":"$\\displaystyle f(x)=\\frac{x}{-x\\sqrt{1+\\frac1{x^2}}}\\to-1$","on":"是負#2"}],"t":[224790,230590]},{"show":["$\\text{兩條：}\\ y=1\\ \\text{（右邊）},\\quad y=-1\\ \\text{（左邊）}$"],"say":"所以有兩條：往右貼近 y 等於 1，往左貼近 y 等於負 1。","board":[{"do":"write","line":"${{bx2:\\displaystyle \\text{兩條：}\\ y=1\\ \\text{（右邊）},\\quad y=-1\\ \\text{（左邊）}}}$","color":"red"},{"do":"box","term":"bx2","color":"red","on":"往左"}],"t":[230590,237890]}]},{"title":"看圖、再一例","beats":[{"show":["往右貼 y = 1，往左貼 y = −1"],"say":"圖上很清楚。只算往右的話，就會漏掉一條。","board":[{"do":"plot","nb":{"spec":{"id":"two","window":[-8,8,-1.6,1.6],"fn":[{"expr":"x/sqrt(x^2+1)","color":"blue","label":"y = x/√(x²+1)"}],"hlines":[{"y":1,"label":"y = 1","color":"red"},{"y":-1,"label":"y = −1","color":"red"}],"height":240}}},{"do":"write","line":"往右貼 y = 1，往左貼 y = −1","color":"violet","on":"的話"}],"t":[237890,244010]},{"show":["有理函數兩頭的極限一定一樣 → 最多一條"],"say":"有理函數往兩頭的極限一定一樣，最多一條。會有兩條的，通常有根號或指數。","board":[{"do":"write","line":"有理函數兩頭的極限一定一樣 → 最多一條"},{"do":"write","line":"　例：$y=e^x$ 只有左邊的 $y=0$；$y=\\arctan x$ 有 $y=\\pm\\frac\\pi2$ 兩條","color":"violet","on":"一條"}],"t":[244010,253750]},{"show":["例：$f(x)=\\dfrac{3x^2+x}{x^2+1}$（次數一樣）"],"say":"再看一個次數一樣的：3x 平方加 x，除以 x 平方加 1。","board":[{"do":"write","line":"例：$f(x)=\\dfrac{3x^2+x}{x^2+1}$（次數一樣）"}],"t":[253750,261670]},{"show":["同除以 $x^2$：$\\dfrac{3+\\frac1x}{1+\\frac1{x^2}}\\to3$","$\\text{水平漸近線}\\ y=3$"],"say":"同除以 x 平方，剩下首項係數比 3。兩個方向都是 3。","board":[{"do":"write","line":"同除以 $x^2$：$\\dfrac{3+\\frac1x}{1+\\frac1{x^2}}\\to3$"},{"do":"write","line":"${{bx3:\\displaystyle \\text{水平漸近線}\\ y=3}}$","on":"剩下"},{"do":"box","term":"bx3","on":"兩個"}],"t":[261670,268770]},{"show":["穿過去了：$f(x)=3\\iff3x^2+x=3x^2+3\\iff x=3$"],"say":"令 f of x 等於 3，3x 平方消掉，得到 x 等於 3。曲線在這裡穿過了水平漸近線。","board":[{"do":"write","line":"穿過去了：$f(x)=3\\iff3x^2+x=3x^2+3\\iff x=3$","color":"red"}],"t":[268770,279070]}]},{"title":"穿過也沒關係","beats":[{"show":["在 (3, 3) 穿過 y = 3：左邊在下方，右邊在上方"],"say":"圖上，曲線在 3 逗號 3 穿過紅線，左邊從下方貼近，右邊從上方貼近。中間怎麼穿都可以。","board":[{"do":"plot","nb":{"spec":{"id":"cross","window":[-12,16,-1,5],"fn":[{"expr":"(3*x^2+x)/(x^2+1)","color":"blue"}],"hlines":[{"y":3,"label":"y = 3","color":"red"}],"points":[{"x":3,"y":3,"label":"(3, 3)","color":"red"}],"height":240}}},{"do":"write","line":"在 (3, 3) 穿過 y = 3：左邊在下方，右邊在上方","color":"violet","on":"穿過"},{"do":"write","line":"　$f(x)-3=\\frac{x-3}{x^2+1}$：$x<3$ 為負（在下方），$x>3$ 為正（在上方）","color":"violet","on":"從上"}],"t":[279070,290340]}],"predict":{"ask":"$f(x)=\\dfrac{2e^x+1}{e^x+1}$ 有幾條水平漸近線？","options":[{"label":"兩條：$y=2$ 與 $y=1$","correct":true},{"label":"一條：$y=2$","why":"只算了 $x\\to\\infty$；往左 $e^x\\to0$，答案是 $1$"},{"label":"一條：$y=1$","why":"只算了 $x\\to-\\infty$；往右要看 $e^x$ 的係數比"},{"label":"沒有","why":"兩個方向都趨近一個有限的數，都是水平漸近線"}]}},{"title":"斜漸近線","beats":[{"show":["定義：若","$\\lim_{x\\to\\infty}\\big[f(x)-(mx+b)\\big]=0\\quad(m\\ne0)$"],"say":"斜漸近線的定義：f of x 減掉 m x 加 b，差趨近 0。也就是曲線跟斜線的垂直距離趨近 0。","board":[{"do":"write","line":"定義：若"},{"do":"write","line":"$\\displaystyle \\lim_{x\\to\\infty}\\big[f(x)-(mx+b)\\big]=0\\quad(m\\ne0)$","on":"差趨"},{"do":"write","line":"則 $y=mx+b$ 是斜漸近線（$x\\to-\\infty$ 也一樣）","color":"gold","on":"就是"}],"t":[304160,314560]},{"show":["有理函數：分子比分母高一次時出現"],"say":"有理函數在分子比分母高一次的時候，會有斜漸近線。","board":[{"do":"write","line":"有理函數：分子比分母高一次時出現"}],"t":[314560,320530]},{"show":["例：$y=\\dfrac{x^2+2x+3}{x}$ 的斜漸近線是 $y=x+k$，求 $k$"],"say":"例子：x 平方加 2x 加 3，除以 x。斜漸近線是 y 等於 x 加 k，求 k。","board":[{"do":"write","line":"例：$y=\\dfrac{x^2+2x+3}{x}$ 的斜漸近線是 $y=x+k$，求 $k$"}],"t":[320530,329540]},{"show":["逐項除：$y=x+2+\\dfrac3x$"],"say":"分母只有 x，逐項除：x 加 2，加 x 分之 3。","board":[{"do":"write","line":"逐項除：$y=x+2+\\dfrac3x$"}],"t":[329540,336110]},{"show":["$y-(x+2)=\\frac3x\\to0\\quad(x\\to\\pm\\infty)$"],"say":"用定義檢查：差是 x 分之 3，往兩頭都趨近 0。","board":[{"do":"write","line":"$\\displaystyle y-(x+2)=\\frac3x\\to0\\quad(x\\to\\pm\\infty)$"}],"t":[336110,341870]},{"show":["$\\text{斜漸近線}\\ y=x+2,\\quad k=2$"],"say":"所以 k 等於 2。x 等於 0 是垂直漸近線，就是開頭那張圖。","board":[{"do":"write","line":"${{bx4:\\displaystyle \\text{斜漸近線}\\ y=x+2,\\quad k=2}}$","color":"red"},{"do":"box","term":"bx4","color":"red","on":"等於#2"},{"do":"write","line":"　想法：商式是那條直線，餘式除以分母趨近 $0$","color":"violet","on":"近線"}],"t":[341870,349240]}],"check":1},{"title":"用長除法","beats":[{"show":["例：$y=\\dfrac{2x^2-3x+1}{x+1}$"],"say":"分母不是單項時，用長除法。例子：2x 平方減 3x 加 1，除以 x 加 1。","board":[{"do":"write","line":"例：$y=\\dfrac{2x^2-3x+1}{x+1}$"}],"t":[358670,369450]},{"show":["• $2x^2\\div x=2x$：減去 $2x(x+1)=2x^2+2x$，剩 $-5x+1$","• $-5x\\div x=-5$：減去 $-5(x+1)=-5x-5$，剩 $6$"],"say":"2x 平方除以 x 得 2x，乘回去減掉，剩負 5x 加 1。再除得負 5，減掉，餘數 6。","board":[{"do":"write","line":"• $2x^2\\div x=2x$：減去 $2x(x+1)=2x^2+2x$，剩 $-5x+1$"},{"do":"write","line":"• $-5x\\div x=-5$：減去 $-5(x+1)=-5x-5$，剩 $6$","on":"5x"}],"t":[369450,379420]},{"show":["$\\frac{2x^2-3x+1}{x+1}=2x-5+\\frac{6}{x+1}$"],"say":"所以原式是 2x 減 5，加 x 加 1 分之 6。","board":[{"do":"write","line":"$\\displaystyle \\frac{2x^2-3x+1}{x+1}=2x-5+\\frac{6}{x+1}$"},{"do":"write","line":"　驗算：$(x+1)(2x-5)+6=2x^2-3x-5+6$","color":"violet","on":"分之"}],"t":[379420,385720]},{"show":["$\\dfrac6{x+1}\\to0$ → 斜漸近線 $y=2x-5$；垂直漸近線 $x=-1$"],"say":"餘式項趨近 0，斜漸近線就是商式 y 等於 2x 減 5；x 等於負 1 是垂直漸近線。","board":[{"do":"write","line":"$\\dfrac6{x+1}\\to0$ → 斜漸近線 $y=2x-5$；垂直漸近線 $x=-1$","color":"red"}],"t":[385720,394920]},{"show":["兩頭都貼著 y = 2x − 5"],"say":"圖上，曲線兩頭都貼著這條斜線。","board":[{"do":"plot","nb":{"spec":{"id":"div","window":[-8,6,-25,10],"fn":[{"expr":"(2*x^2-3*x+1)/(x+1)","color":"blue"},{"expr":"2*x-5","color":"red","dash":true,"label":"y = 2x−5"}],"vlines":[{"x":-1,"label":"x = −1","color":"red"}],"height":250}}},{"do":"write","line":"兩頭都貼著 y = 2x − 5","color":"violet","on":"都貼"}],"t":[394920,399360]},{"show":["有理函數：次數差 $\\le0$ → 水平；差 $=1$ → 斜；差 $\\ge2$ → 都沒有"],"say":"有理函數整理：分子次數不大於分母，有水平的；多一次，有斜的；多兩次以上，都沒有。","board":[{"do":"write","line":"有理函數：次數差 $\\le0$ → 水平；差 $=1$ → 斜；差 $\\ge2$ → 都沒有"},{"do":"write","line":"　差 $\\ge2$ 時商式是二次以上，曲線彎上去，貼不到直線","color":"violet","on":"多一"}],"t":[399360,409890]}]},{"title":"試一題","beats":[{"show":["$y=\\dfrac{x^3+1}{x^2+1}$ 的斜漸近線是？"],"say":"用長除法試試看。","t":[409890,421480]}],"check":2},{"title":"試一題","beats":[{"show":["不是有理函數：用定義反推","$m=\\lim_{x\\to\\infty}\\frac{f(x)}{x},\\quad b=\\lim_{x\\to\\infty}\\big[f(x)-mx\\big]$"],"say":"補充：不是有理函數時，用定義反推。斜率 m 是 f 除以 x 的極限，截距 b 是 f 減 m x 的極限。","board":[{"do":"write","line":"不是有理函數：用定義反推"},{"do":"write","line":"${{bx5:\\displaystyle m=\\lim_{x\\to\\infty}\\frac{f(x)}{x},\\quad b=\\lim_{x\\to\\infty}\\big[f(x)-mx\\big]}}$","on":"義反"},{"do":"box","term":"bx5","on":"的極#1"},{"do":"write","line":"　例：$\\sqrt{x^2+2x}$ 往右貼 $y=x+1$，往左貼 $y=-x-1$","color":"violet","on":"的極#2"}],"t":[421480,441210]}]},{"title":"重點整理","beats":[{"show":["• 垂直 $x=a$：有一側極限是 $\\pm\\infty$；有理函數先約分，約掉的是洞","• 水平 $y=L$：$x\\to\\infty$、$x\\to-\\infty$ 分開算，最多兩條"],"say":"整理：垂直漸近線看單邊極限，先約分，約掉的是洞；水平的兩個方向分開算；斜的是差趨近零，用長除法取商式；水平和斜的都可以被穿過。","board":[{"do":"write","line":"• 垂直 $x=a$：有一側極限是 $\\pm\\infty$；有理函數先約分，約掉的是洞"},{"do":"write","line":"• 水平 $y=L$：$x\\to\\infty$、$x\\to-\\infty$ 分開算，最多兩條","on":"約分"},{"do":"write","line":"• 斜 $y=mx+b$：$f(x)-(mx+b)\\to0$；有理函數用長除法取商","on":"分開"},{"do":"write","line":"• 水平、斜漸近線可以被穿過","on":"取商"}],"t":[441210,455710]},{"show":["下一課：函數完整分析 I：用漸近線當骨架"],"say":"下一課，把漸近線、增減、極值放在一起，完整分析一個函數。","board":[{"do":"write","line":"下一課：函數完整分析 I：用漸近線當骨架"}],"t":[455710,464744]}]}],"checks":[{"ask":"$y=\\dfrac{x^2-9}{x^2-x-6}$ 的垂直漸近線是？","options":[{"label":"只有 $x=-2$","correct":true},{"label":"$x=3$ 和 $x=-2$","why":"沒先約分：$x-3$ 約掉了，$x=3$ 是洞"},{"label":"只有 $x=3$","why":"把洞當成漸近線，卻把真正約不掉的 $x+2$ 漏了"},{"label":"$x=\\pm3$","why":"看成分子的零點了；漸近線看的是分母"}]},{"ask":"若 $f(x)=2x-1+\\dfrac{5}{x^2+1}$，斜漸近線是？","options":[{"label":"$y=2x-1$","correct":true},{"label":"$y=2x+4$","why":"把餘式的 $5$ 也加進去了；那一項趨近 $0$，不屬於直線"},{"label":"$y=2x$","why":"截距 $-1$ 不能丟：$f(x)-2x\\to-1$，不是 $0$"},{"label":"$y=5$","why":"那是分子的常數；$f$ 往兩頭跑到 $\\pm\\infty$，沒有水平漸近線"}]},{"ask":"$y=\\dfrac{x^3+1}{x^2+1}$ 的斜漸近線是？","options":[{"label":"$y=x$","correct":true},{"label":"$y=x+1$","why":"把分子的常數 $1$ 當成截距；長除法的商只有 $x$"},{"label":"沒有，因為分子比分母高","why":"高一次正好是有斜漸近線的情況；高兩次以上才沒有"},{"label":"$y=1$","why":"那是首項係數比；次數不一樣，不是水平漸近線"}]}],"practice":[{"id":"lec-04-q3a","core":true},{"id":"lec-01-q4b","core":true},{"id":"cx-curve-004","core":true},{"id":"lec-04-q3b","core":true},{"id":"cx-curve-005","core":true},{"id":"cx-curve-006","core":true},{"id":"cg-3b-004","core":true},{"id":"cg-3b-001","core":true},{"id":"lx-app-002"},{"id":"lx-app-008"},{"id":"sk-016"},{"id":"cg-3b-003"},{"id":"cg-3b-002"},{"id":"cg-3b-005"},{"id":"sk-022","challenge":true,"note":"挑戰：畫出 $x-\\frac{4}{x}$，要同時畫出 $x=0$ 與 $y=x$ 兩條漸近線。"}]},"curve-sketching-1":{"id":"curve-sketching-1","prerequisites":["asymptotes","increasing-decreasing","first-derivative-test"],"next":["curve-sketching-2"],"related":["domain-range"],"objectives":["照固定順序分析一個函數：定義域、截距、對稱、漸近線、增減與極值","用奇偶對稱省掉一半的工作","把分析結果組合成一張草圖的骨架，並解釋為什麼「局部極大可以比局部極小低」"],"concept":[{"heading":"① 為什麼要有固定順序","body":["想畫 $f(x)=\\dfrac{x^2}{x-1}$，只描幾個點：","用平滑曲線連起來？","描點會漏掉：斷掉的地方、衝到無窮、轉彎的位置"],"tex":["f(-1)=-\\tfrac12,\\ f(0)=0,\\ f(2)=4,\\ f(3)=\\tfrac92"]},{"heading":"② 五個步驟","body":["1. 定義域：哪裡有定義、哪裡斷掉","2. 截距：與 $x$、$y$ 軸的交點","3. 對稱：$f(-x)=f(x)$ 偶、$f(-x)=-f(x)$ 奇","4. 漸近線：垂直、水平、斜","5. 增減與極值：$f'$ 的正負","下一課再加第六步：$f''$ 看凹性","順序的道理：前面的結果，後面會用到","• 偶函數：對 $y$ 軸鏡射","• 奇函數：對原點轉半圈"]},{"heading":"② 例一：前四步","body":["$f(x)=\\dfrac{x^2}{x-1}$","1. 定義域：$x\\ne1$","2. 截距：$f(0)=0$；$f(x)=0\\iff x=0$ → 只有 $(0,0)$","3. 對稱：$f(-x)=\\dfrac{x^2}{-x-1}$，不等於 $\\pm f(x)$ → 沒有","4. 漸近線：","• 垂直 $x=1$：$x\\to1^+$ 時 $\\to+\\infty$；$x\\to1^-$ 時 $\\to-\\infty$","• 長除法：$\\dfrac{x^2}{x-1}=x+1+\\dfrac1{x-1}$","斜漸近線 $y=x+1$；沒有水平漸近線","驗算：$(x-1)(x+1)+1=x^2$"]},{"heading":"② 例一：增減與極值","body":["臨界點：$x=0,\\ 2$；分母 $(x-1)^2>0$，正負只看 $x(x-2)$","檢查點：$f'(-1)=f'(3)=\\frac34>0$，$f'(\\frac12)=f'(\\frac32)=-3<0$","• $x=0$：$+$ 變 $-$ → 局部極大 $f(0)=0$","• $x=2$：$-$ 變 $+$ → 局部極小 $f(2)=4$"],"tex":["f'(x)=\\frac{2x(x-1)-x^2}{(x-1)^2}=\\frac{x(x-2)}{(x-1)^2}","\\begin{array}{c|c|c|c|c}x&(-\\infty,0)&(0,1)&(1,2)&(2,\\infty)\\\\\\hline f'&+&-&-&+\\\\\\hline f&\\nearrow&\\searrow&\\searrow&\\nearrow\\end{array}"]},{"heading":"③ 把骨架連起來","body":["先畫：漸近線（虛線）、截距、極值點","再照增減表，沿著漸近線連線","怪事：局部極大 $0$ 比局部極小 $4$ 還低","數值確認：$f(1.5)=4.5$、$f(0.5)=-0.5$","「局部」只跟附近比","兩個極值在 $x=1$ 的兩側，中間被漸近線隔開，彼此不比較","沒有斷點時，相鄰的極大與極小之間 $f$ 單調，極大一定比較高"]},{"heading":"④ 例二：用對稱省一半","body":["$g(x)=\\dfrac{x}{x^2+1}$","1. 定義域：$x^2+1>0$，全體實數","2. 截距：只有 $(0,0)$","3. $g(-x)=\\dfrac{-x}{x^2+1}=-g(x)$ → 奇函數","4. 漸近線：沒有垂直；$x\\to\\infty$ 時 $\\dfrac{x}{x^2+1}\\to0$","奇函數：$x\\to-\\infty$ 也是 $0$，只有一條 $y=0$","5. $g'(x)=\\dfrac{(x^2+1)-x\\cdot2x}{(x^2+1)^2}=\\dfrac{1-x^2}{(x^2+1)^2}$","只看 $x\\ge0$：$0<x<1$ 時 $g'>0$；$x>1$ 時 $g'<0$","$x=1$：局部極大 $g(1)=\\frac12$","對稱：$x=-1$ 是局部極小 $g(-1)=-\\frac12$"]},{"heading":"④ 例二的骨架","body":["這一次極大、極小也是最大、最小：值域 $\\big[-\\frac12,\\frac12\\big]$"]},{"heading":"重點整理","body":["• 順序：定義域 → 截距 → 對稱 → 漸近線 → 增減與極值","• 描點會漏掉斷點、無窮、轉彎；分析不會","• 奇、偶函數：只做 $x\\ge0$，另一半鏡射或轉半圈","• 增減區間不能跨過斷點寫成一段","• 「局部」只跟附近比：被漸近線隔開時，極大可以比極小低","下一課：加入 $f''$：凹性與反曲點，完成總表"]}],"workedExamples":[{"title":"有垂直與斜漸近線","prompt":"分析 $f(x)=\\frac{x^2}{x-1}$：定義域、截距、對稱、漸近線、增減、極值。","problemId":"lec-04-q3b","steps":["定義域：$x\\ne 1$。截距：$f(0)=0$，$f(x)=0$ 只有 $x=0$，所以只有原點。","對稱：$f(-x)=\\frac{x^2}{-x-1}$，既不等於 $f(x)$ 也不等於 $-f(x)$，沒有對稱。","垂直漸近線 $x=1$：$x\\to 1^+$ 時分子 $\\to 1$、分母 $\\to 0^+$，$f\\to+\\infty$；$x\\to 1^-$ 時分母 $\\to 0^-$，$f\\to-\\infty$。","斜漸近線：$x^2=(x-1)(x+1)+1$，$f(x)=x+1+\\frac{1}{x-1}$，$\\frac{1}{x-1}\\to 0$，所以是 $y=x+1$。沒有水平漸近線。","$f'(x)=\\frac{x(x-2)}{(x-1)^2}$（〈增減區間〉範例 3）：遞增 $(-\\infty,0)$、$(2,\\infty)$；遞減 $(0,1)$、$(1,2)$。","$x=0$ 由正變負：局部極大 $f(0)=0$。$x=2$ 由負變正：局部極小 $f(2)=\\frac{4}{1}=4$。"],"answer":"定義域 $x\\ne 1$；截距 $(0,0)$；無對稱；漸近線 $x=1$、$y=x+1$；局部極大 $(0,0)$、局部極小 $(2,4)$","note":"局部極大 $0$ 比局部極小 $4$ 低：兩點分別在 $x=1$ 的左右兩個分支上。"},{"title":"用對稱省一半","prompt":"分析 $f(x)=\\frac{x}{x^2+1}$：定義域、截距、對稱、漸近線、增減、極值。","problemId":"db-ext-013","steps":["定義域：$x^2+1\\ge 1$，全體實數。截距：只有原點 $(0,0)$。","對稱：$f(-x)=\\frac{-x}{x^2+1}=-f(x)$，奇函數，對原點對稱。下面只看 $x\\ge 0$。","漸近線：沒有垂直漸近線；分子 1 次、分母 2 次，$x\\to\\infty$ 時 $f\\to 0$，水平漸近線 $y=0$（由奇對稱，$x\\to-\\infty$ 也是 $y=0$）。","$f'(x)=\\frac{(x^2+1)-x\\cdot 2x}{(x^2+1)^2}=\\frac{1-x^2}{(x^2+1)^2}$。在 $x\\ge 0$ 上：$0\\le x<1$ 時 $f'>0$，$x>1$ 時 $f'<0$。","$x=1$ 是局部極大，$f(1)=\\frac{1}{2}$。翻到左邊：$x=-1$ 是局部極小 $f(-1)=-\\frac{1}{2}$；遞增 $(-1,1)$，遞減 $(-\\infty,-1)$、$(1,\\infty)$。"],"answer":"奇函數；漸近線 $y=0$；遞增 $(-1,1)$；局部極大 $(1,\\frac{1}{2})$、局部極小 $(-1,-\\frac{1}{2})$"}],"pitfalls":["跳過定義域，結果在 $f$ 沒定義的地方畫了曲線。","$x$ 截距與 $y$ 截距弄反：$y$ 截距是 $f(0)$。","只算 $x\\to\\infty$ 的漸近線，漏了 $x\\to-\\infty$。","看到局部極大比局部極小低，以為算錯；先看兩點中間是不是隔著垂直漸近線。","奇函數只分析了右半邊，忘了把極大翻成極小。"],"voice":"f058020d","sections":[{"title":"為什麼要有固定順序","beats":[{"show":["想畫 $f(x)=\\dfrac{x^2}{x-1}$，只描幾個點：","$f(-1)=-\\tfrac12,\\ f(0)=0,\\ f(2)=4,\\ f(3)=\\tfrac92$"],"say":"想畫 x 平方除以 x 減 1 的圖。最直接的做法是描點：負 1、0、2、3，算出四個函數值。","board":[{"do":"write","line":"想畫 $f(x)=\\dfrac{x^2}{x-1}$，只描幾個點："},{"do":"write","line":"$\\displaystyle f(-1)=-\\tfrac12,\\ f(0)=0,\\ f(2)=4,\\ f(3)=\\tfrac92$","on":"做法"}],"t":[4620,15680]},{"show":["用平滑曲線連起來？"],"say":"然後用一條平滑曲線把它們連起來，看起來好像沒問題？","board":[{"do":"write","line":"用平滑曲線連起來？"}],"t":[15680,22750]},{"show":["只描點連線：完全錯"],"say":"這樣連是錯的。x 等於 1 沒有定義，曲線在那裡往上下衝，描點完全看不出來。","board":[{"do":"plot","nb":{"spec":{"id":"dots","window":[-3,5,-6,9],"lines":[{"from":[-1,-0.5],"to":[0,0],"color":"red","dash":true},{"from":[0,0],"to":[2,4],"color":"red","dash":true},{"from":[2,4],"to":[3,4.5],"color":"red","dash":true}],"points":[{"x":-1,"y":-0.5,"color":"red"},{"x":0,"y":0,"color":"red"},{"x":2,"y":4,"color":"red"},{"x":3,"y":4.5,"color":"red"}],"height":260}}},{"do":"write","line":"只描點連線：完全錯","color":"violet","on":"曲線"}],"t":[22750,31760]},{"show":["描點會漏掉：斷掉的地方、衝到無窮、轉彎的位置"],"say":"描點會漏掉三種東西：斷掉的地方、衝到無窮的地方、還有轉彎的位置。所以要照固定的順序分析，一項都不漏。","board":[{"do":"write","line":"描點會漏掉：斷掉的地方、衝到無窮、轉彎的位置","color":"red"}],"t":[31760,51270]}]},{"title":"五個步驟","beats":[{"show":["1. 定義域：哪裡有定義、哪裡斷掉","2. 截距：與 $x$、$y$ 軸的交點"],"say":"五個步驟：定義域、截距、對稱、漸近線，最後用 f prime 看增減與極值。","board":[{"do":"write","line":"1. 定義域：哪裡有定義、哪裡斷掉"},{"do":"write","line":"2. 截距：與 $x$、$y$ 軸的交點","on":"義域"},{"do":"write","line":"3. 對稱：$f(-x)=f(x)$ 偶、$f(-x)=-f(x)$ 奇","on":"對稱"},{"do":"write","line":"4. 漸近線：垂直、水平、斜","on":"最後"},{"do":"write","line":"5. 增減與極值：$f'$ 的正負","on":"pr"},{"do":"write","line":"　下一課再加第六步：$f''$ 看凹性","color":"violet","on":"看增"}],"t":[51270,59670]},{"show":["順序的道理：前面的結果，後面會用到"],"say":"順序是有道理的：定義域告訴你哪裡斷掉，漸近線要在斷掉的地方找；對稱能讓後面的工作省一半。","board":[{"do":"write","line":"順序的道理：前面的結果，後面會用到"}],"t":[59670,70020]}],"proof":true,"order":{"ask":"完整分析函數的順序","steps":[{"label":"定義域"},{"label":"截距","why":"先要有上一步：定義域"},{"label":"對稱","why":"先要有上一步：截距"},{"label":"漸近線","why":"先要有上一步：對稱"},{"label":"增減與極值","why":"先要有上一步：漸近線"}]}},{"title":"五個步驟","beats":[{"show":["• 偶函數：對 $y$ 軸鏡射","• 奇函數：對原點轉半圈"],"say":"對稱的兩種：偶函數對 y 軸鏡射；奇函數對原點轉半圈。有對稱的話，只要分析 x 大於等於 0 的一半。","board":[{"do":"write","line":"• 偶函數：對 $y$ 軸鏡射"},{"do":"write","line":"• 奇函數：對原點轉半圈","on":"有對"}],"t":[79050,90760]}]},{"title":"例一：前四步","beats":[{"show":["$f(x)=\\dfrac{x^2}{x-1}$"],"say":"用例一走一遍：x 平方除以 x 減 1。","board":[{"do":"write","line":"$f(x)=\\dfrac{x^2}{x-1}$"}],"t":[90760,95400]},{"show":["1. 定義域：$x\\ne1$"],"say":"第一步，分母不能是 0，定義域是 x 不等於 1。","board":[{"do":"write","line":"1. 定義域：$x\\ne1$"}],"t":[95400,100800]},{"show":["2. 截距：$f(0)=0$；$f(x)=0\\iff x=0$ → 只有 $(0,0)$"],"say":"第二步，截距。x 等於 0 時 y 是 0；y 等於 0 只有 x 等於 0。所以只有原點。","board":[{"do":"write","line":"2. 截距：$f(0)=0$；$f(x)=0\\iff x=0$ → 只有 $(0,0)$"}],"t":[100800,110530]},{"show":["3. 對稱：$f(-x)=\\dfrac{x^2}{-x-1}$，不等於 $\\pm f(x)$ → 沒有"],"say":"第三步，把負 x 代進去，分母變負 x 減 1，跟原來不同，也不是相反數，沒有奇偶對稱。","board":[{"do":"write","line":"3. 對稱：$f(-x)=\\dfrac{x^2}{-x-1}$，不等於 $\\pm f(x)$ → 沒有"}],"t":[110530,121830]},{"show":["4. 漸近線：","• 垂直 $x=1$：$x\\to1^+$ 時 $\\to+\\infty$；$x\\to1^-$ 時 $\\to-\\infty$"],"say":"第四步，漸近線。x 趨近 1，分子趨近 1 是正的；右邊分母是小正數，往正無限大，左邊往負無限大。","board":[{"do":"write","line":"4. 漸近線："},{"do":"write","line":"• 垂直 $x=1$：$x\\to1^+$ 時 $\\to+\\infty$；$x\\to1^-$ 時 $\\to-\\infty$","on":"右邊"}],"t":[121830,133400]},{"show":["• 長除法：$\\dfrac{x^2}{x-1}=x+1+\\dfrac1{x-1}$"],"say":"分子比分母高一次，做長除法：x 加 1，加 x 減 1 分之 1。","board":[{"do":"write","line":"• 長除法：$\\dfrac{x^2}{x-1}=x+1+\\dfrac1{x-1}$"}],"t":[133400,140400]},{"show":["斜漸近線 $y=x+1$；沒有水平漸近線"],"say":"所以斜漸近線是 y 等於 x 加 1，沒有水平漸近線。","board":[{"do":"write","line":"斜漸近線 $y=x+1$；沒有水平漸近線","color":"gold"},{"do":"write","line":"　驗算：$(x-1)(x+1)+1=x^2$","color":"violet","on":"沒有"}],"t":[140400,146900]}]},{"title":"例一：增減與極值","beats":[{"show":["$f'(x)=\\frac{2x(x-1)-x^2}{(x-1)^2}=\\frac{x(x-2)}{(x-1)^2}$"],"say":"第五步，用商的微分。分子整理成 x 乘 x 減 2，分母是 x 減 1 的平方。","board":[{"do":"write","line":"$\\displaystyle f'(x)=\\frac{2x(x-1)-x^2}{(x-1)^2}=\\frac{x(x-2)}{(x-1)^2}$"}],"t":[146900,155300]},{"show":["臨界點：$x=0,\\ 2$；分母 $(x-1)^2>0$，正負只看 $x(x-2)$"],"say":"f prime 等於 0 在 x 等於 0 和 2。分母是平方，一定是正的，正負只看分子 x 乘 x 減 2。","board":[{"do":"write","line":"臨界點：$x=0,\\ 2$；分母 $(x-1)^2>0$，正負只看 $x(x-2)$"}],"t":[155300,166700]},{"show":["$\\begin{array}{c|c|c|c|c}x&(-\\infty,0)&(0,1)&(1,2)&(2,\\infty)\\\\\\hline f'&+&-&-&+\\\\\\hline f&\\nearrow&\\searrow&\\searrow&\\nearrow\\end{array}$"],"say":"列成表：0 的左邊是正的，遞增；0 到 2 之間是負的，遞減，中間跨過斷點 x 等於 1；2 以後又是正的。","board":[{"do":"write","line":"$\\displaystyle {\\begin{array}{c|c|c|c|c}x&(-\\infty,0)&(0,1)&(1,2)&(2,\\infty)\\\\\\hline f'&+&-&-&+\\\\\\hline f&\\nearrow&\\searrow&\\searrow&\\nearrow\\end{array}}$"},{"do":"write","line":"　檢查點：$f'(-1)=f'(3)=\\frac34>0$，$f'(\\frac12)=f'(\\frac32)=-3<0$","color":"violet","on":"遞減"}],"t":[166700,180500]},{"show":["• $x=0$：$+$ 變 $-$ → 局部極大 $f(0)=0$","• $x=2$：$-$ 變 $+$ → 局部極小 $f(2)=4$"],"say":"一階導數判別：在 0，從正變負，是局部極大，值是 0；在 2，從負變正，是局部極小，值是 4。","board":[{"do":"write","line":"• $x=0$：$+$ 變 $-$ → 局部極大 $f(0)=0$"},{"do":"write","line":"• $x=2$：$-$ 變 $+$ → 局部極小 $f(2)=4$","on":"從負"}],"t":[180500,191630]}],"check":0},{"title":"把骨架連起來","beats":[{"show":["先畫：漸近線（虛線）、截距、極值點"],"say":"現在把骨架連起來。先畫兩條漸近線，再點上原點、和兩個極值點。","board":[{"do":"write","line":"先畫：漸近線（虛線）、截距、極值點"}],"t":[201050,209480]},{"show":["再照增減表，沿著漸近線連線"],"say":"再照增減表連：左邊往上爬到原點，然後往下衝向 x 等於 1；右邊從上面衝下來，到 2 逗號 4 轉彎，再往上貼著斜線。","board":[{"do":"write","line":"再照增減表，沿著漸近線連線"}],"t":[209480,221750]},{"show":["骨架：兩條漸近線＋兩個極值點"],"say":"這就是完整的圖。跟一開始描點的版本完全不一樣。","board":[{"do":"plot","nb":{"spec":{"id":"sk1","window":[-5,6,-8,10],"fn":[{"expr":"x^2/(x-1)","color":"blue"},{"expr":"x+1","color":"red","dash":true,"label":"y = x+1"}],"vlines":[{"x":1,"label":"x = 1","color":"red"}],"points":[{"x":0,"y":0,"color":"blue"},{"x":2,"y":4,"color":"blue"}],"labels":[{"x":-2.6,"y":1.3,"text":"極大 (0, 0)"},{"x":2.4,"y":1.5,"text":"極小 (2, 4)"}],"height":280}}},{"do":"write","line":"骨架：兩條漸近線＋兩個極值點","color":"violet","on":"始描"}],"t":[221750,228700]},{"show":["怪事：局部極大 $0$ 比局部極小 $4$ 還低"],"say":"有一件怪事：局部極大值是 0，局部極小值卻是 4，極大比極小還低。","board":[{"do":"write","line":"怪事：局部極大 $0$ 比局部極小 $4$ 還低","color":"red"},{"do":"write","line":"　數值確認：$f(1.5)=4.5$、$f(0.5)=-0.5$","color":"violet","on":"部極#2"}],"t":[228700,236480]},{"show":["「局部」只跟附近比"],"say":"原因是「局部」只跟附近比。x 等於 0 只比它附近的點高；x 等於 2 只比它附近的點低。","board":[{"do":"write","line":"「局部」只跟附近比","color":"gold"}],"t":[236480,246100]},{"show":["兩個極值在 $x=1$ 的兩側，中間被漸近線隔開，彼此不比較"],"say":"而且兩個極值在斷點的兩側，中間隔著一條垂直漸近線，曲線根本沒有連起來，所以不用比較。","board":[{"do":"write","line":"兩個極值在 $x=1$ 的兩側，中間被漸近線隔開，彼此不比較"},{"do":"write","line":"　沒有斷點時，相鄰的極大與極小之間 $f$ 單調，極大一定比較高","color":"violet","on":"漸近"}],"t":[246100,256320]}]},{"title":"例二：用對稱省一半","beats":[{"show":["$g(x)=\\dfrac{x}{x^2+1}$"],"say":"例二：x 除以 x 平方加 1。","board":[{"do":"write","line":"$g(x)=\\dfrac{x}{x^2+1}$"}],"t":[256320,261850]},{"show":["1. 定義域：$x^2+1>0$，全體實數","2. 截距：只有 $(0,0)$"],"say":"分母永遠是正的，定義域是全體實數。截距只有原點。","board":[{"do":"write","line":"1. 定義域：$x^2+1>0$，全體實數"},{"do":"write","line":"2. 截距：只有 $(0,0)$","on":"全體"}],"t":[261850,268750]},{"show":["3. $g(-x)=\\dfrac{-x}{x^2+1}=-g(x)$ → 奇函數"],"say":"把負 x 代進去，得到負的 g of x，是奇函數。所以只要分析 x 大於等於 0，另一半轉半圈就好。","board":[{"do":"write","line":"3. $g(-x)=\\dfrac{-x}{x^2+1}=-g(x)$ → 奇函數","color":"gold"}],"t":[268750,279350]},{"show":["4. 漸近線：沒有垂直；$x\\to\\infty$ 時 $\\dfrac{x}{x^2+1}\\to0$"],"say":"沒有垂直漸近線。分母次數比較高，x 趨近無限大時趨近 0，水平漸近線是 y 等於 0。","board":[{"do":"write","line":"4. 漸近線：沒有垂直；$x\\to\\infty$ 時 $\\dfrac{x}{x^2+1}\\to0$"},{"do":"write","line":"　奇函數：$x\\to-\\infty$ 也是 $0$，只有一條 $y=0$","color":"violet","on":"限大"}],"t":[279350,289930]},{"show":["5. $g'(x)=\\dfrac{(x^2+1)-x\\cdot2x}{(x^2+1)^2}=\\dfrac{1-x^2}{(x^2+1)^2}$"],"say":"第五步，商的微分，分子整理成 1 減 x 平方。","board":[{"do":"write","line":"5. $g'(x)=\\dfrac{(x^2+1)-x\\cdot2x}{(x^2+1)^2}=\\dfrac{1-x^2}{(x^2+1)^2}$"}],"t":[289930,295290]},{"show":["只看 $x\\ge0$：$0<x<1$ 時 $g'>0$；$x>1$ 時 $g'<0$"],"say":"只看右半邊：x 在 0 到 1 之間，1 減 x 平方是正的，遞增；x 大於 1，是負的，遞減。","board":[{"do":"write","line":"只看 $x\\ge0$：$0<x<1$ 時 $g'>0$；$x>1$ 時 $g'<0$"}],"t":[295290,305290]},{"show":["$x=1$：局部極大 $g(1)=\\frac12$"],"say":"所以 x 等於 1 是局部極大，值是 2 分之 1。","board":[{"do":"write","line":"$x=1$：局部極大 $g(1)=\\frac12$","color":"gold"}],"t":[305290,310890]},{"show":["對稱：$x=-1$ 是局部極小 $g(-1)=-\\frac12$"],"say":"用奇對稱，另一半不用再算：x 等於負 1 是局部極小，值是負 2 分之 1。","board":[{"do":"write","line":"對稱：$x=-1$ 是局部極小 $g(-1)=-\\frac12$","color":"red"}],"t":[310890,319590]}]},{"title":"例二的骨架","beats":[{"show":["奇函數：右半邊轉半圈得到左半邊"],"say":"圖上，右半邊從原點爬到 1 逗號 2 分之 1，再慢慢降回 0；左半邊就是轉半圈。","board":[{"do":"plot","nb":{"spec":{"id":"sk2","window":[-6,6,-0.8,0.8],"fn":[{"expr":"x/(x^2+1)","color":"blue"}],"hlines":[{"y":0,"color":"red"}],"points":[{"x":1,"y":0.5,"color":"blue"},{"x":-1,"y":-0.5,"color":"blue"}],"labels":[{"x":1.2,"y":0.66,"text":"(1, 1/2)"},{"x":-3.6,"y":-0.66,"text":"(−1, −1/2)"}],"height":260}}},{"do":"write","line":"奇函數：右半邊轉半圈得到左半邊","color":"violet","on":"再慢"}],"t":[319590,328260]},{"show":["這一次極大、極小也是最大、最小：值域 $\\big[-\\frac12,\\frac12\\big]$"],"say":"這一次沒有斷點，極大值 2 分之 1 也是整條曲線的最大值，值域是負 2 分之 1 到 2 分之 1。","board":[{"do":"write","line":"這一次極大、極小也是最大、最小：值域 $\\big[-\\frac12,\\frac12\\big]$"}],"t":[328260,339560]}],"predict":{"ask":"$h(x)=\\dfrac{x^2}{x^2+1}$ 有什麼對稱？可以省哪一半？","options":[{"label":"偶函數：只分析 $x\\ge0$，再對 $y$ 軸鏡射","correct":true},{"label":"奇函數：只分析 $x\\ge0$，再轉半圈","why":"$(-x)^2=x^2$，正負號沒有跑出來，是偶函數"},{"label":"沒有對稱","why":"代 $-x$ 試試：分子分母都只有 $x^2$"},{"label":"對 $x$ 軸對稱","why":"函數圖不會對 $x$ 軸對稱（同一個 $x$ 只有一個 $y$）"}]}},{"title":"重點整理","beats":[{"show":["• 順序：定義域 → 截距 → 對稱 → 漸近線 → 增減與極值","• 描點會漏掉斷點、無窮、轉彎；分析不會"],"say":"整理：照定義域、截距、對稱、漸近線、增減的順序；有對稱就只做一半；增減區間不能跨過斷點；局部極值只跟附近比，所以極大可以比極小低。","board":[{"do":"write","line":"• 順序：定義域 → 截距 → 對稱 → 漸近線 → 增減與極值"},{"do":"write","line":"• 描點會漏掉斷點、無窮、轉彎；分析不會","on":"漸近"},{"do":"write","line":"• 奇、偶函數：只做 $x\\ge0$，另一半鏡射或轉半圈","on":"稱就"},{"do":"write","line":"• 增減區間不能跨過斷點寫成一段","on":"跨過"},{"do":"write","line":"• 「局部」只跟附近比：被漸近線隔開時，極大可以比極小低","on":"所以"}],"t":[359130,374340]},{"show":["下一課：加入 $f''$：凹性與反曲點，完成總表"],"say":"下一課，加入二階導數，看凹性與反曲點，把圖畫完整。","board":[{"do":"write","line":"下一課：加入 $f''$：凹性與反曲點，完成總表"}],"t":[374340,382616]}]}],"checks":[{"ask":"$f$ 在哪裡遞減？","options":[{"label":"$(0,1)$ 與 $(1,2)$","correct":true},{"label":"$(0,2)$","why":"$x=1$ 沒有定義，不能寫成一整段"},{"label":"$(-\\infty,0)$ 與 $(2,\\infty)$","why":"這兩段 $f'>0$，是遞增"},{"label":"$(1,2)$","why":"漏了 $(0,1)$：那裡 $x>0$、$x-2<0$，$f'<0$"}]}],"practice":[{"id":"lec-04-q3a","core":true},{"id":"lec-04-q3b","core":true},{"id":"lec-04-q3c","core":true},{"id":"si-int-019","core":true},{"id":"sk-018","core":true},{"id":"sk-016","core":true},{"id":"cg-3b-006","core":true},{"id":"sk-019"},{"id":"sk-017"},{"id":"gr-012"},{"id":"gr-010"},{"id":"cg-3b-007"},{"id":"cg-3b-008"},{"id":"cg-3b-009"},{"id":"sk-021","challenge":true,"note":"挑戰：$x+\\frac{1}{x}$ 是奇函數，有垂直漸近線 $x=0$ 與斜漸近線 $y=x$；局部極大 $-2$ 比局部極小 $2$ 低。"}]},"curve-sketching-2":{"id":"curve-sketching-2","prerequisites":["curve-sketching-1","concavity","inflection-points"],"next":["optimization-basics"],"related":["second-derivative-test"],"objectives":["在〈函數完整分析 I〉的骨架上加入 $f''$：凹性區間與反曲點","把所有結果整理成一張總表，按表自己畫出完整的圖","用幾個一致性檢查抓出計算錯誤"],"concept":[{"heading":"① 第六步：$f''$","body":["骨架有了，還差彎的方向","• $f''>0$：凹向上 $\\cup$","• $f''<0$：凹向下 $\\cap$","反曲點：凹性改變、而且曲線在那裡有定義的點","候選：$f''=0$ 或 $f''$ 不存在的點；還要確認兩側真的變號","例一（接續 I）：$f(x)=\\dfrac{x^2}{x-1}$","寫成 $f(x)=x+1+\\dfrac1{x-1}$","跟 I 的 $f'=\\frac{x(x-2)}{(x-1)^2}$ 是同一個式子：通分即得","• $x>1$：$f''>0$，凹向上","• $x<1$：$f''<0$，凹向下"],"tex":["f'(x)=1-\\frac{1}{(x-1)^2},\\qquad f''(x)=\\frac{2}{(x-1)^3}"]},{"heading":"① 沒有反曲點","body":["凹性在 $x=1$ 改變，但 $x=1$ 不在定義域","$f''$ 的分子是 $2$，永遠不是 $0$，也沒有其他候選","例二（接續 I）：$g(x)=\\dfrac{x}{x^2+1}$","上一課：$g'=\\dfrac{1-x^2}{(x^2+1)^2}$","分子：$-2x^3-2x-4x+4x^3=2x^3-6x$"],"tex":["\\text{例一沒有反曲點}","g''=\\frac{-2x(x^2+1)-4x(1-x^2)}{(x^2+1)^3}","=\\frac{2x(x^2-3)}{(x^2+1)^3}"]},{"heading":"① 三個反曲點","body":["$g''=0$：$x=0,\\ \\pm\\sqrt3$；分母恆正，正負看 $2x(x^2-3)$","檢查點：$g''(\\pm1)=\\mp\\frac12$，$g''(\\pm2)=\\pm0.032$","$\\frac{\\sqrt3}4\\approx0.433$；奇函數，算一個就有另一個"],"tex":["\\begin{array}{c|c|c|c|c}x&(-\\infty,-\\sqrt3)&(-\\sqrt3,0)&(0,\\sqrt3)&(\\sqrt3,\\infty)\\\\\\hline g''&-&+&-&+\\\\\\hline&\\cap&\\cup&\\cap&\\cup\\end{array}","(0,0),\\quad\\Big(\\sqrt3,\\tfrac{\\sqrt3}4\\Big),\\quad\\Big(-\\sqrt3,-\\tfrac{\\sqrt3}4\\Big)"]},{"heading":"② 總表","body":["把 $f'$、$f''$ 放進同一張表，每一段就知道形狀","例一 $f(x)=\\dfrac{x^2}{x-1}$：分點 $x=0,\\ 1,\\ 2$","關鍵點：極大 $(0,0)$、極小 $(2,4)$、無反曲點","漸近線：$x=1$、$y=x+1$"],"tex":["\\begin{array}{c|c|c|c|c}x&(-\\infty,0)&(0,1)&(1,2)&(2,\\infty)\\\\\\hline f'&+&-&-&+\\\\\\hline f''&-&-&+&+\\\\\\hline f&\\nearrow\\,\\cap&\\searrow\\,\\cap&\\searrow\\,\\cup&\\nearrow\\,\\cup\\end{array}"]},{"heading":"② 例二的總表","body":["奇函數，只列 $x\\ge0$；分點 $x=0,\\ 1,\\ \\sqrt3$","照表畫右半邊：","• 從 $(0,0)$ 往上，彎成蓋子，到 $(1,\\frac12)$ 最高","• 往下，還是蓋子，到 $(\\sqrt3,\\frac{\\sqrt3}4)$ 換彎法","• 變成碗，慢慢貼近 $y=0$","左半邊：對原點轉半圈"],"tex":["\\begin{array}{c|c|c|c}x&(0,1)&(1,\\sqrt3)&(\\sqrt3,\\infty)\\\\\\hline g'&+&-&-\\\\\\hline g''&-&-&+\\\\\\hline g&\\nearrow\\,\\cap&\\searrow\\,\\cap&\\searrow\\,\\cup\\end{array}"]},{"heading":"③ 一致性檢查","body":["畫之前，先用這幾條抓錯：","• 極值與凹性：極大處不能凹向上，極小處不能凹向下","• 貼近漸近線：從上方遞減貼近水平線 → 最後要凹向上","• 對稱：$f$ 奇 → $f'$ 偶、$f''$ 奇；$f$ 偶 → $f'$ 奇、$f''$ 偶","• 分點：變號只能發生在零點或斷點","例：例一 $f''(0)=-2<0$（極大，凹向下），$f''(2)=2>0$（極小，凹向上）","例二：極大 $(1,\\frac12)$ 凹向下，往右又要凹向上貼近 $0$","→ 中間一定有反曲點"]},{"heading":"③ 試一題","body":["對稱是必要條件，不是保證","錯在哪：$-2x-4x=-6x$，誤寫成 $+6x$"]},{"heading":"④ 從頭做一次","body":["$h(x)=e^{-x^2}$","• 定義域：全體實數；$h>0$，沒有 $x$ 截距，$y$ 截距 $(0,1)$","• 對稱：$h(-x)=h(x)$，偶函數，只做 $x\\ge0$","• 漸近線：$x\\to\\infty$ 時 $e^{-x^2}\\to0$ → $y=0$","$x>0$ 時 $h'<0$ → 遞減；$x=0$ 是極大 $h(0)=1$","$(-2x)'e^{-x^2}+(-2x)(-2x)e^{-x^2}$"],"tex":["h'(x)=-2x\\,e^{-x^2}","h''(x)=(4x^2-2)\\,e^{-x^2}"]},{"heading":"④ 總表與圖","body":["$h''=0\\iff x=\\pm\\dfrac1{\\sqrt2}\\approx\\pm0.71$","反曲點 $\\Big(\\pm\\frac1{\\sqrt2},\\ e^{-1/2}\\Big)\\approx(\\pm0.71,\\ 0.61)$","一致性：偶函數 → $h'$ 奇、$h''$ 偶 ；極大處 $h''(0)=-2<0$"],"tex":["\\begin{array}{c|c|c}x&(0,\\frac1{\\sqrt2})&(\\frac1{\\sqrt2},\\infty)\\\\\\hline h'&-&-\\\\\\hline h''&-&+\\\\\\hline h&\\searrow\\,\\cap&\\searrow\\,\\cup\\end{array}"]},{"heading":"④ 猜猜看","body":["它跟例二一樣：奇函數、一個極大、一個極小、往兩頭貼近 $0$","$y'=(1-2x^2)e^{-x^2}$；$y''=(4x^3-6x)e^{-x^2}$"]},{"heading":"重點整理","body":["• 第六步：$f''$ 定凹性；反曲點要變號而且在圖上","• 總表：分點 = $f'$、$f''$ 的零點 + 斷點；每段寫出 $\\nearrow\\searrow$、$\\cup\\cap$","• 一致性：極值配凹性、貼近漸近線、奇偶、分點","• 檢查過了不代表一定對：多用幾條","下一課：最佳化：把極值用在真實問題上"]}],"workedExamples":[{"title":"接續 I：沒有反曲點的例子","prompt":"$f(x)=\\frac{x^2}{x-1}$。加入凹性，完成總表。","problemId":"lec-04-q3d","steps":["$f(x)=x+1+\\frac{1}{x-1}$，$f''(x)=\\frac{2}{(x-1)^3}$。$f''$ 沒有零點，只在 $x=1$（不在定義域）換號：$x<1$ 凹向下，$x>1$ 凹向上。沒有反曲點。","總表切點：$0$、$1$、$2$。$(-\\infty,0)$：$f'$ $+$、$f''$ $-$，上坡越來越緩。$(0,1)$：$f'$ $-$、$f''$ $-$，下坡越來越陡，衝向 $-\\infty$。$(1,2)$：$f'$ $-$、$f''$ $+$，從 $+\\infty$ 下來、越來越緩。$(2,\\infty)$：$f'$ $+$、$f''$ $+$，上坡、貼近 $y=x+1$。","檢查：局部極大 $(0,0)$ 在凹向下的左分支、局部極小 $(2,4)$ 在凹向上的右分支，一致。"],"answer":"凹向下 $(-\\infty,1)$、凹向上 $(1,\\infty)$；無反曲點"},{"title":"接續 I：三個反曲點","prompt":"$f(x)=\\frac{x}{x^2+1}$。求凹性與反曲點。","problemId":"cx-curve-007","steps":["$f'(x)=(1-x^2)(x^2+1)^{-2}$。乘法法則：$f''(x)=-2x(x^2+1)^{-2}+(1-x^2)\\cdot(-2)(x^2+1)^{-3}\\cdot 2x$。","提出 $(x^2+1)^{-3}$：$f''(x)=\\frac{-2x(x^2+1)-4x(1-x^2)}{(x^2+1)^3}=\\frac{2x^3-6x}{(x^2+1)^3}=\\frac{2x(x^2-3)}{(x^2+1)^3}$。","零點 $x=0$、$\\pm\\sqrt{3}$，都是一次因式，都換號。$x<-\\sqrt{3}$：$-$；$-\\sqrt{3}<x<0$：$+$；$0<x<\\sqrt{3}$：$-$；$x>\\sqrt{3}$：$+$。","凹向上：$(-\\sqrt{3},0)$、$(\\sqrt{3},\\infty)$；凹向下：$(-\\infty,-\\sqrt{3})$、$(0,\\sqrt{3})$。反曲點 $(-\\sqrt{3},-\\frac{\\sqrt{3}}{4})$、$(0,0)$、$(\\sqrt{3},\\frac{\\sqrt{3}}{4})$（$f(\\sqrt{3})=\\frac{\\sqrt{3}}{4}\\approx 0.433$）。","檢查：$f$ 是奇函數，$f''$ 也應該是奇函數，$\\frac{2x(x^2-3)}{(x^2+1)^3}$ 確實是。局部極大 $(1,\\frac{1}{2})$ 在凹向下的 $(0,\\sqrt{3})$ 裡，一致。"],"answer":"3 個反曲點：$x=-\\sqrt{3}$、$0$、$\\sqrt{3}$"},{"title":"從頭做一次","prompt":"完整分析 $f(x)=e^{-x^2}$。","problemId":"sk-031","steps":["定義域全體實數；$e^{-x^2}>0$，沒有 $x$ 截距，$y$ 截距 $(0,1)$；$f(-x)=f(x)$，偶函數。$x\\to\\pm\\infty$ 時 $-x^2\\to-\\infty$，$f\\to 0$，水平漸近線 $y=0$。","$f'(x)=-2xe^{-x^2}$：$x<0$ 遞增、$x>0$ 遞減，局部極大 $f(0)=1$。","$f''(x)=-2e^{-x^2}+(-2x)(-2x)e^{-x^2}=(4x^2-2)e^{-x^2}$，零點 $x=\\pm\\frac{1}{\\sqrt{2}}\\approx\\pm 0.707$，都換號。$|x|<\\frac{1}{\\sqrt{2}}$ 凹向下，$|x|>\\frac{1}{\\sqrt{2}}$ 凹向上。","反曲點 $(\\pm\\frac{1}{\\sqrt{2}},e^{-1/2})$，$e^{-1/2}\\approx 0.607$。檢查：極大 $(0,1)$ 在凹向下的段裡；兩條尾巴從上方貼近 $y=0$，凹向上，一致。"],"answer":"偶函數；$y=0$；極大 $(0,1)$；反曲點 $(\\pm\\frac{1}{\\sqrt{2}},e^{-1/2})$"}],"pitfalls":["$f'$ 與 $f''$ 的切點分開列兩張表，最後拼不起來；要合成一張。","把定義域斷開的點也寫成反曲點。","極大點畫在凹向上的段裡卻沒發現矛盾。","$f''$ 的乘法法則或連鎖律漏一項，三個反曲點只找到一個。"],"voice":"742518ac","sections":[{"title":"第六步：$f''$","beats":[{"show":["骨架有了，還差彎的方向"],"say":"上一課用五個步驟搭好骨架。這一課加第六步：二階導數，決定曲線往哪邊彎。","board":[{"do":"write","line":"骨架有了，還差彎的方向"}],"t":[2280,12440]},{"show":["• $f''>0$：凹向上 $\\cup$","• $f''<0$：凹向下 $\\cap$"],"say":"複習一下：二階導數大於 0，凹向上，像碗；小於 0，凹向下，像蓋子。","board":[{"do":"write","line":"• $f''>0$：凹向上 $\\cup$"},{"do":"write","line":"• $f''<0$：凹向下 $\\cap$","on":"像碗"}],"t":[12440,20930]},{"show":["反曲點：凹性改變、而且曲線在那裡有定義的點"],"say":"反曲點是凹性改變的點，而且那一點必須在圖形上。","board":[{"do":"write","line":"反曲點：凹性改變、而且曲線在那裡有定義的點","color":"gold"},{"do":"write","line":"　候選：$f''=0$ 或 $f''$ 不存在的點；還要確認兩側真的變號","color":"violet","on":"而且"}],"t":[20930,27410]},{"show":["例一（接續 I）：$f(x)=\\dfrac{x^2}{x-1}$"],"say":"接續上一課的例一。用長除法的形式微分最快。","board":[{"do":"write","line":"例一（接續 I）：$f(x)=\\dfrac{x^2}{x-1}$"},{"do":"write","line":"寫成 $f(x)=x+1+\\dfrac1{x-1}$","on":"長除"}],"t":[27410,33590]},{"show":["$f'(x)=1-\\frac{1}{(x-1)^2},\\qquad f''(x)=\\frac{2}{(x-1)^3}$"],"say":"一階導數是 1 減 x 減 1 平方分之 1，再微一次，得到 x 減 1 的三次方分之 2。","board":[{"do":"write","line":"$\\displaystyle f'(x)=1-\\frac{1}{(x-1)^2},\\qquad f''(x)=\\frac{2}{(x-1)^3}$"},{"do":"write","line":"　跟 I 的 $f'=\\frac{x(x-2)}{(x-1)^2}$ 是同一個式子：通分即得","color":"violet","on":"再微"}],"t":[33590,44640]},{"show":["• $x>1$：$f''>0$，凹向上","• $x<1$：$f''<0$，凹向下"],"say":"x 大於 1，分母是正的，凹向上；x 小於 1，分母是負的，凹向下。","board":[{"do":"write","line":"• $x>1$：$f''>0$，凹向上"},{"do":"write","line":"• $x<1$：$f''<0$，凹向下","on":"小於"}],"t":[44640,53370]}]},{"title":"沒有反曲點","beats":[{"show":["凹性在 $x=1$ 改變，但 $x=1$ 不在定義域"],"say":"凹性在 x 等於 1 的兩側改變了，但 x 等於 1 不在定義域，圖上沒有這個點。","board":[{"do":"write","line":"凹性在 $x=1$ 改變，但 $x=1$ 不在定義域"}],"t":[53370,61970]},{"show":["$\\text{例一沒有反曲點}$"],"say":"所以例一沒有反曲點。凹性改變的地方，是一條垂直漸近線。","board":[{"do":"write","line":"${{bx1:\\displaystyle \\text{例一沒有反曲點}}}$","color":"red"},{"do":"box","term":"bx1","color":"red","on":"凹性"},{"do":"write","line":"　$f''$ 的分子是 $2$，永遠不是 $0$，也沒有其他候選","color":"violet","on":"是一"}],"t":[61970,69170]}],"check":0},{"title":"沒有反曲點","beats":[{"show":["例二（接續 I）：$g(x)=\\dfrac{x}{x^2+1}$"],"say":"例二。上一課算過一階導數。","board":[{"do":"write","line":"例二（接續 I）：$g(x)=\\dfrac{x}{x^2+1}$"},{"do":"write","line":"上一課：$g'=\\dfrac{1-x^2}{(x^2+1)^2}$","on":"算過"}],"t":[78430,83060]},{"show":["$g''=\\frac{-2x(x^2+1)-4x(1-x^2)}{(x^2+1)^3}$"],"say":"再用商的微分。分子是負 2x 乘 x 平方加 1，減 4x 乘 1 減 x 平方，分母約掉一個 x 平方加 1 以後剩三次方。","board":[{"do":"write","line":"$\\displaystyle g''=\\frac{-2x(x^2+1)-4x(1-x^2)}{(x^2+1)^3}$"}],"t":[83060,96060]},{"show":["$=\\frac{2x(x^2-3)}{(x^2+1)^3}$"],"say":"分子展開整理，得到 2x 乘 x 平方減 3。","board":[{"do":"write","line":"${{bx2:\\displaystyle =\\frac{2x(x^2-3)}{(x^2+1)^3}}}$"},{"do":"box","term":"bx2","on":"得到"},{"do":"write","line":"　分子：$-2x^3-2x-4x+4x^3=2x^3-6x$","color":"violet","on":"平方"}],"t":[96060,101780]}]},{"title":"三個反曲點","beats":[{"show":["$g''=0$：$x=0,\\ \\pm\\sqrt3$；分母恆正，正負看 $2x(x^2-3)$"],"say":"二階導數等於 0 在 0 和正負根號 3。分母恆正，正負只看分子。","board":[{"do":"write","line":"$g''=0$：$x=0,\\ \\pm\\sqrt3$；分母恆正，正負看 $2x(x^2-3)$"}],"t":[101780,109610]},{"show":["$\\begin{array}{c|c|c|c|c}x&(-\\infty,-\\sqrt3)&(-\\sqrt3,0)&(0,\\sqrt3)&(\\sqrt3,\\infty)\\\\\\hline g''&-&+&-&+\\\\\\hline&\\cap&\\cup&\\cap&\\cup\\end{array}$"],"say":"從左到右：負、正、負、正。凹性換了三次，三個點都有定義，所以三個都是反曲點。","board":[{"do":"write","line":"$\\displaystyle {\\begin{array}{c|c|c|c|c}x&(-\\infty,-\\sqrt3)&(-\\sqrt3,0)&(0,\\sqrt3)&(\\sqrt3,\\infty)\\\\\\hline g''&-&+&-&+\\\\\\hline&\\cap&\\cup&\\cap&\\cup\\end{array}}$"},{"do":"write","line":"　檢查點：$g''(\\pm1)=\\mp\\frac12$，$g''(\\pm2)=\\pm0.032$","color":"violet","on":"三個#1"}],"t":[109610,120570]},{"show":["$(0,0),\\quad\\Big(\\sqrt3,\\tfrac{\\sqrt3}4\\Big),\\quad\\Big(-\\sqrt3,-\\tfrac{\\sqrt3}4\\Big)$"],"say":"三個反曲點：原點，根號 3 逗號 4 分之根號 3，還有它轉半圈的對稱點。","board":[{"do":"write","line":"${{bx3:\\displaystyle (0,0),\\quad\\Big(\\sqrt3,\\tfrac{\\sqrt3}4\\Big),\\quad\\Big(-\\sqrt3,-\\tfrac{\\sqrt3}4\\Big)}}$","color":"red"},{"do":"box","term":"bx3","color":"red","on":"逗號"},{"do":"write","line":"　$\\frac{\\sqrt3}4\\approx0.433$；奇函數，算一個就有另一個","color":"violet","on":"還有"}],"t":[120570,128630]},{"show":["紅點：三個反曲點；藍點：極值"],"say":"圖上，紅點是反曲點。極大之後曲線先凹向下，過了根號 3 才凹向上，慢慢貼近 0。","board":[{"do":"plot","nb":{"spec":{"id":"inf2","window":[-6,6,-0.7,0.7],"fn":[{"expr":"x/(x^2+1)","color":"blue"}],"hlines":[{"y":0,"color":"red"}],"points":[{"x":0,"y":0,"color":"red"},{"x":"sqrt(3)","y":"sqrt(3)/4","color":"red"},{"x":"-sqrt(3)","y":"-sqrt(3)/4","color":"red"},{"x":1,"y":0.5,"color":"blue"},{"x":-1,"y":-0.5,"color":"blue"}],"height":240}}},{"do":"write","line":"紅點：三個反曲點；藍點：極值","color":"violet","on":"過了"}],"t":[128630,139330]}]},{"title":"總表","beats":[{"show":["把 $f'$、$f''$ 放進同一張表，每一段就知道形狀"],"say":"第二個重點：總表。把一階和二階導數放進同一張表，每一段的形狀就確定了。","board":[{"do":"write","line":"把 $f'$、$f''$ 放進同一張表，每一段就知道形狀"}],"t":[139330,150130]},{"show":["例一 $f(x)=\\dfrac{x^2}{x-1}$：分點 $x=0,\\ 1,\\ 2$","$\\begin{array}{c|c|c|c|c}x&(-\\infty,0)&(0,1)&(1,2)&(2,\\infty)\\\\\\hline f'&+&-&-&+\\\\\\hline f''&-&-&+&+\\\\\\hline f&\\nearrow\\,\\cap&\\searrow\\,\\cap&\\searrow\\,\\cup&\\nearrow\\,\\cup\\end{array}$"],"say":"例一的分點是 0、1、2：一階導數的零點加上斷點。每段寫下兩個導數的正負，最後一列就是形狀：增減，加上凹向上或凹向下。","board":[{"do":"write","line":"例一 $f(x)=\\dfrac{x^2}{x-1}$：分點 $x=0,\\ 1,\\ 2$"},{"do":"write","line":"$\\displaystyle {\\begin{array}{c|c|c|c|c}x&(-\\infty,0)&(0,1)&(1,2)&(2,\\infty)\\\\\\hline f'&+&-&-&+\\\\\\hline f''&-&-&+&+\\\\\\hline f&\\nearrow\\,\\cap&\\searrow\\,\\cap&\\searrow\\,\\cup&\\nearrow\\,\\cup\\end{array}}$","on":"兩個"}],"t":[150130,166560]},{"show":["關鍵點：極大 $(0,0)$、極小 $(2,4)$、無反曲點","漸近線：$x=1$、$y=x+1$"],"say":"再把關鍵點和漸近線列在表的下面。","board":[{"do":"write","line":"關鍵點：極大 $(0,0)$、極小 $(2,4)$、無反曲點"},{"do":"write","line":"漸近線：$x=1$、$y=x+1$","on":"線列"}],"t":[166560,171110]},{"show":["左邊整段凹向下，右邊整段凹向上"],"say":"照表畫：左邊這一支整段都凹向下，右邊整段都凹向上。跟上一課的圖一樣，但現在每一段彎的方向都有根據。","board":[{"do":"plot","nb":{"spec":{"id":"full1","window":[-5,6,-8,10],"fn":[{"expr":"x^2/(x-1)","color":"blue"},{"expr":"x+1","color":"red","dash":true}],"vlines":[{"x":1,"color":"red"}],"points":[{"x":0,"y":0,"color":"blue"},{"x":2,"y":4,"color":"blue"}],"height":250}}},{"do":"write","line":"左邊整段凹向下，右邊整段凹向上","color":"violet","on":"跟上"}],"t":[171110,185750]}]},{"title":"例二的總表","beats":[{"show":["奇函數，只列 $x\\ge0$；分點 $x=0,\\ 1,\\ \\sqrt3$","$\\begin{array}{c|c|c|c}x&(0,1)&(1,\\sqrt3)&(\\sqrt3,\\infty)\\\\\\hline g'&+&-&-\\\\\\hline g''&-&-&+\\\\\\hline g&\\nearrow\\,\\cap&\\searrow\\,\\cap&\\searrow\\,\\cup\\end{array}$"],"say":"例二是奇函數，只列右半邊。分點是 0、1、根號 3。第一段遞增凹向下；第二段遞減凹向下；第三段遞減凹向上。","board":[{"do":"write","line":"奇函數，只列 $x\\ge0$；分點 $x=0,\\ 1,\\ \\sqrt3$"},{"do":"write","line":"${{bx4:\\displaystyle {\\begin{array}{c|c|c|c}x&(0,1)&(1,\\sqrt3)&(\\sqrt3,\\infty)\\\\\\hline g'&+&-&-\\\\\\hline g''&-&-&+\\\\\\hline g&\\nearrow\\,\\cap&\\searrow\\,\\cap&\\searrow\\,\\cup\\end{array}}}}$","on":"根號"},{"do":"box","term":"bx4","on":"第二"}],"t":[185750,204980]},{"show":["照表畫右半邊：","• 從 $(0,0)$ 往上，彎成蓋子，到 $(1,\\frac12)$ 最高"],"say":"照表畫右半邊：從原點往上，像蓋子一樣彎，到 1 逗號 2 分之 1 最高；往下，還是蓋子，到根號 3 換成碗；最後慢慢貼近 0。","board":[{"do":"write","line":"照表畫右半邊："},{"do":"write","line":"• 從 $(0,0)$ 往上，彎成蓋子，到 $(1,\\frac12)$ 最高","on":"一樣"},{"do":"write","line":"• 往下，還是蓋子，到 $(\\sqrt3,\\frac{\\sqrt3}4)$ 換彎法","on":"最高"},{"do":"write","line":"• 變成碗，慢慢貼近 $y=0$","on":"換成"}],"t":[204980,218180]},{"show":["左半邊：對原點轉半圈"],"say":"左半邊，轉半圈就好。","board":[{"do":"write","line":"左半邊：對原點轉半圈"}],"t":[218180,231000]}]},{"title":"一致性檢查","beats":[{"show":["畫之前，先用這幾條抓錯：","• 極值與凹性：極大處不能凹向上，極小處不能凹向下"],"say":"第三個重點：一致性檢查。極大處不能凹向上；從上方遞減貼近水平線，最後一定凹向上；奇函數的一階導數是偶的、二階是奇的；變號只能在零點或斷點。","board":[{"do":"write","line":"畫之前，先用這幾條抓錯："},{"do":"write","line":"• 極值與凹性：極大處不能凹向上，極小處不能凹向下","on":"大處"},{"do":"write","line":"• 貼近漸近線：從上方遞減貼近水平線 → 最後要凹向上","on":"近水"},{"do":"write","line":"• 對稱：$f$ 奇 → $f'$ 偶、$f''$ 奇；$f$ 偶 → $f'$ 奇、$f''$ 偶","on":"函數"},{"do":"write","line":"• 分點：變號只能發生在零點或斷點","on":"奇的"}],"t":[231000,247950]},{"show":["例：例一 $f''(0)=-2<0$（極大，凹向下），$f''(2)=2>0$（極小，凹向上）"],"say":"拿例一試：極大點 0 的二階導數是負 2，凹向下；極小點 2 是正 2，凹向上。都對得上。","board":[{"do":"write","line":"例：例一 $f''(0)=-2<0$（極大，凹向下），$f''(2)=2>0$（極小，凹向上）"}],"t":[247950,260430]},{"show":["例二：極大 $(1,\\frac12)$ 凹向下，往右又要凹向上貼近 $0$","→ 中間一定有反曲點"],"say":"例二：極大點凹向下，但往右要從上方貼近 0，最後得凹向上。所以 1 的右邊一定有反曲點，剛好就是根號 3。","board":[{"do":"write","line":"例二：極大 $(1,\\frac12)$ 凹向下，往右又要凹向上貼近 $0$"},{"do":"write","line":"→ 中間一定有反曲點","color":"gold","on":"向上"}],"t":[260430,273320]}]},{"title":"試一題","beats":[{"show":["某生把 $g(x)=\\dfrac{x}{x^2+1}$ 算成 $g''=\\dfrac{2x(x^2+3)}{(x^2+1)^3}$（錯的）。哪一條檢查抓不到這個錯？"],"say":"試一題：哪一條檢查抓不到這個錯？","t":[273320,286440]}],"check":1},{"title":"試一題","beats":[{"show":["對稱是必要條件，不是保證"],"say":"這題的重點：對稱檢查過了不代表算對，它只能抓出一部分的錯。所以要多用幾條一起檢查。","board":[{"do":"write","line":"對稱是必要條件，不是保證"},{"do":"write","line":"　錯在哪：$-2x-4x=-6x$，誤寫成 $+6x$","color":"violet","on":"能抓"}],"t":[286440,297240]}]},{"title":"從頭做一次","beats":[{"show":["$h(x)=e^{-x^2}$"],"say":"最後，從頭完整做一次：e 的負 x 平方次方。","board":[{"do":"write","line":"$h(x)=e^{-x^2}$"}],"t":[297240,302750]},{"show":["• 定義域：全體實數；$h>0$，沒有 $x$ 截距，$y$ 截距 $(0,1)$"],"say":"定義域是全體實數。指數永遠是正的，沒有 x 截距；y 截距是 0 逗號 1。","board":[{"do":"write","line":"• 定義域：全體實數；$h>0$，沒有 $x$ 截距，$y$ 截距 $(0,1)$"}],"t":[302750,311350]},{"show":["• 對稱：$h(-x)=h(x)$，偶函數，只做 $x\\ge0$"],"say":"把負 x 代進去不變，是偶函數，只要做右半邊。","board":[{"do":"write","line":"• 對稱：$h(-x)=h(x)$，偶函數，只做 $x\\ge0$"}],"t":[311350,316900]},{"show":["• 漸近線：$x\\to\\infty$ 時 $e^{-x^2}\\to0$ → $y=0$"],"say":"x 趨近無限大，指數趨近 0，水平漸近線 y 等於 0。沒有垂直漸近線。","board":[{"do":"write","line":"• 漸近線：$x\\to\\infty$ 時 $e^{-x^2}\\to0$ → $y=0$"}],"t":[316900,326040]},{"show":["$h'(x)=-2x\\,e^{-x^2}$"],"say":"一階導數，用連鎖律：負 2x 乘 e 的負 x 平方。","board":[{"do":"write","line":"$\\displaystyle h'(x)=-2x\\,e^{-x^2}$"}],"t":[326040,331840]},{"show":["$x>0$ 時 $h'<0$ → 遞減；$x=0$ 是極大 $h(0)=1$"],"say":"x 大於 0，一階導數是負的，遞減。左半邊對稱過去遞增，所以 x 等於 0 是極大，值是 1。","board":[{"do":"write","line":"$x>0$ 時 $h'<0$ → 遞減；$x=0$ 是極大 $h(0)=1$"}],"t":[331840,341990]},{"show":["$h''(x)=(4x^2-2)\\,e^{-x^2}$"],"say":"二階導數用乘積律，兩項提出 e 的負 x 平方，整理成 4x 平方減 2，乘 e 的負 x 平方。","board":[{"do":"write","line":"${{bx5:\\displaystyle h''(x)=(4x^2-2)\\,e^{-x^2}}}$"},{"do":"box","term":"bx5","on":"的負#1"},{"do":"write","line":"　$(-2x)'e^{-x^2}+(-2x)(-2x)e^{-x^2}$","color":"violet","on":"方減"}],"t":[341990,354950]}]},{"title":"總表與圖","beats":[{"show":["$h''=0\\iff x=\\pm\\dfrac1{\\sqrt2}\\approx\\pm0.71$","$\\begin{array}{c|c|c}x&(0,\\frac1{\\sqrt2})&(\\frac1{\\sqrt2},\\infty)\\\\\\hline h'&-&-\\\\\\hline h''&-&+\\\\\\hline h&\\searrow\\,\\cap&\\searrow\\,\\cup\\end{array}$"],"say":"二階導數等於 0 在正負根號 2 分之 1，大約 0.71。右半邊的總表只有兩段：先遞減凹向下，再遞減凹向上。","board":[{"do":"write","line":"$h''=0\\iff x=\\pm\\dfrac1{\\sqrt2}\\approx\\pm0.71$"},{"do":"write","line":"$\\displaystyle {\\begin{array}{c|c|c}x&(0,\\frac1{\\sqrt2})&(\\frac1{\\sqrt2},\\infty)\\\\\\hline h'&-&-\\\\\\hline h''&-&+\\\\\\hline h&\\searrow\\,\\cap&\\searrow\\,\\cup\\end{array}}$","on":"71"}],"t":[354950,366950]},{"show":["反曲點 $\\Big(\\pm\\frac1{\\sqrt2},\\ e^{-1/2}\\Big)\\approx(\\pm0.71,\\ 0.61)$"],"say":"反曲點是正負根號 2 分之 1，高度 e 的負 2 分之 1 次方，大約 0.61。","board":[{"do":"write","line":"反曲點 $\\Big(\\pm\\frac1{\\sqrt2},\\ e^{-1/2}\\Big)\\approx(\\pm0.71,\\ 0.61)$","color":"red"}],"t":[366950,376450]},{"show":["鐘形曲線：極大 (0, 1)，兩個反曲點"],"say":"這就是有名的鐘形曲線。頂端凹向下，過了兩個反曲點變成凹向上，往兩邊貼近 0。","board":[{"do":"plot","nb":{"spec":{"id":"bell","window":[-3,3,-0.2,1.2],"fn":[{"expr":"e^(-x^2)","color":"blue"}],"hlines":[{"y":0,"color":"red"}],"points":[{"x":0,"y":1,"color":"blue"},{"x":"1/sqrt(2)","y":"e^(-0.5)","color":"red"},{"x":"-1/sqrt(2)","y":"e^(-0.5)","color":"red"}],"height":240}}},{"do":"write","line":"鐘形曲線：極大 (0, 1)，兩個反曲點","color":"violet","on":"兩個"}],"t":[376450,385950]},{"show":["一致性：偶函數 → $h'$ 奇、$h''$ 偶 ；極大處 $h''(0)=-2<0$"],"say":"檢查一下：一階導數是奇的，二階是偶的；極大處二階導數是負 2，凹向下。全部對得上。","board":[{"do":"write","line":"一致性：偶函數 → $h'$ 奇、$h''$ 偶 ；極大處 $h''(0)=-2<0$"}],"t":[385950,397100]}]},{"title":"猜猜看","beats":[{"show":["$y=xe^{-x^2}$ 有幾個反曲點？"],"say":"最後猜猜看：x 乘 e 的負 x 平方，有幾個反曲點？想想它跟例二長得多像。","t":[397100,407360]}],"predict":{"ask":"$y=xe^{-x^2}$ 有幾個反曲點？","options":[{"label":"3 個","correct":true},{"label":"2 個","why":"跟 $e^{-x^2}$ 搞混了；這是奇函數，$x=0$ 也是"},{"label":"1 個","why":"只看到原點；奇函數有極大 → 往右還要變回凹向上"},{"label":"0 個","why":"$y''$ 的多項式部分 $4x^3-6x$ 有三個實根"}]}},{"title":"猜猜看","beats":[{"show":["它跟例二一樣：奇函數、一個極大、一個極小、往兩頭貼近 $0$"],"say":"它跟例二是同一種形狀：奇函數，一個極大一個極小，往兩頭貼近 0。所以也是三個反曲點。","board":[{"do":"write","line":"它跟例二一樣：奇函數、一個極大、一個極小、往兩頭貼近 $0$"},{"do":"write","line":"　$y'=(1-2x^2)e^{-x^2}$；$y''=(4x^3-6x)e^{-x^2}$","color":"violet","on":"極小"}],"t":[407360,425430]}]},{"title":"重點整理","beats":[{"show":["• 第六步：$f''$ 定凹性；反曲點要變號而且在圖上","• 總表：分點 = $f'$、$f''$ 的零點 + 斷點；每段寫出 $\\nearrow\\searrow$、$\\cup\\cap$"],"say":"整理：第六步用二階導數決定凹性，反曲點要變號而且在圖上；把所有分點放進總表，每段寫出增減和凹性；畫之前用幾條一致性檢查抓錯。","board":[{"do":"write","line":"• 第六步：$f''$ 定凹性；反曲點要變號而且在圖上"},{"do":"write","line":"• 總表：分點 = $f'$、$f''$ 的零點 + 斷點；每段寫出 $\\nearrow\\searrow$、$\\cup\\cap$","on":"反曲"},{"do":"write","line":"• 一致性：極值配凹性、貼近漸近線、奇偶、分點","on":"分點"},{"do":"write","line":"• 檢查過了不代表一定對：多用幾條","on":"畫之"}],"t":[425430,439510]},{"show":["下一課：最佳化：把極值用在真實問題上"],"say":"下一課，把極值用在真實的問題上：最佳化。","board":[{"do":"write","line":"下一課：最佳化：把極值用在真實問題上"}],"t":[439510,446537]}]}],"checks":[{"ask":"$y=\\dfrac1x$ 的反曲點是？","options":[{"label":"沒有","correct":true},{"label":"$(0,0)$","why":"$x=0$ 沒有定義，圖上沒有這個點"},{"label":"$x=0$","why":"凹性在這裡改變沒錯，但反曲點必須在圖形上"},{"label":"$(1,1)$ 和 $(-1,-1)$","why":"那兩點 $y''=\\pm2\\ne0$，凹性沒有改變"}]},{"ask":"某生把 $g(x)=\\dfrac{x}{x^2+1}$ 算成 $g''=\\dfrac{2x(x^2+3)}{(x^2+1)^3}$（錯的）。哪一條檢查抓不到這個錯？","options":[{"label":"對稱：$g''$ 應該是奇函數","correct":true},{"label":"極值與凹性：極大 $(1,\\frac12)$ 應凹向下","why":"抓得到：錯的式子 $g''(1)=1>0$，極大處凹向上，矛盾"},{"label":"極大之後要貼近 $y=0$：右邊必有反曲點","why":"抓得到：錯的式子在 $x>0$ 永遠不是 $0$，右邊找不到反曲點"}]}],"practice":[{"id":"cw-001","core":true},{"id":"cx-curve-007","core":true},{"id":"sk-012","core":true},{"id":"sk-031","core":true},{"id":"cw-004","core":true},{"id":"cg-3b-010","core":true},{"id":"sk-029"},{"id":"sk-020"},{"id":"gx-030"},{"id":"cw-014"},{"id":"sk-030"},{"id":"cg-3b-011"},{"id":"sk-023","challenge":true,"note":"挑戰：$\\frac{x}{x^2-1}$ 有兩條垂直漸近線、奇對稱，反曲點只有原點。"}]}});
